-- NaCCA curriculum for Basic 2: 207 indicators (English Language, Ghanaian Language, History, Mathematics, Religious & Moral Education, Science).
-- Needs 20261029_curriculum_subject_key.sql first. Safe to run again: it replaces these subjects for Basic 2.
delete from public.curriculum_items
 where lower(class_name) = 'basic 2' and subject_key in ('english', 'ghanaian language', 'history', 'maths', 'rme', 'science');

