insert into public.curriculum_items
  (class_name, subject, subject_key, strand, sub_strand, content_standard_code, content_standard, indicator_code, indicator, exemplar, sort_order)
values
('Basic 2', 'English Language', 'english', 'Oral Language', 'Songs', 'B2.1.1.1', 'Demonstrate understanding of a variety of songs', 'B2.1.1.1.1', 'Interpret familiar songs', 'Identify some familiar songs from learners’ locality.; Teach the songs with themes from their locality.; Discuss the moral values of the songs.; Let learners sing songs using gestures appropriately.; Have learners interpret the songs in their own words.', 10),
('Basic 2', 'English Language', 'english', 'Oral Language', 'Rhymes', 'B2.1.2.1', 'Show understanding of a variety of literary pieces', 'B2.1.2.1.1', 'Interpret rhymes and tongue-twisters in own words', 'Revise some familiar rhymes and tongue-twisters learnt.; Select a rhyme from learners.; As learners listen and observe, perform the rhyme (Recite it, accompanied with actions and gestures, two or three times).; Recite lines of the rhyme as learners join in and repeat lines after you.; Teach the accompanying actions through demonstration.; Let learners repeat lines of the rhyme on their own accompanied with appropriate actions.; Through questions, have learners interpret the rhymes in their own words.', 20),
('Basic 2', 'English Language', 'english', 'Oral Language', 'Story Telling', 'B2.1.4.1', 'Respond to stories', 'B2.1.4.1.1', 'Identify characters in a story and relate them to real life situations', 'Choose a story from learners’ background.; Tell the story with appropriate actions, gestures, facial expressions, etc.; Have learners retell the story and answer questions on it.; Let learners say whether or not they have enjoyed the story and why.; Put learners into groups to identify the characters and their actions and relate them to real life situations. NOTE. Use pictures/sketches, real objects, etc.', 30),
('Basic 2', 'English Language', 'english', 'Oral Language', 'Story Telling', 'B2.1.4.1', 'Respond to stories', 'B2.1.4.1.2', 'Retell stories sequentially, following story structure (beginning, middle and ending)', 'Revise the previous story told by having learners recall some of the characters.; Discuss the moral lessons/values of the story.; Let learners retell the story sequentially, following story structure (beginning, middle and ending).; Let learners relate the story to real life situations.', 40),
('Basic 2', 'English Language', 'english', 'Oral Language', 'Story Telling', 'B2.1.4.1', 'Respond to stories', 'B2.1.4.1.3', 'Tell stories from cultural background', 'Revise some stories learners have heard.; Tell the story as learners listen.; Let learners tell their own stories.; Discuss the moral lessons/values in stories told.', 50),
('Basic 2', 'English Language', 'english', 'Oral Language', 'Dramatisation and Role Play', 'B2.1.5.1', 'Perform Stories', 'B2.1.5.1.1', 'Dramatise/role-play stories heard or read', 'Have learners select an interesting story heard or read in class.; Retell the story.; Discuss the story and have learners recall main events and characters.; Select characters and assign them roles to play.; Let learners dramatise/role-play the story.; Discuss moral values from the story.; Have learners say whether or not they have enjoyed the drama and why.', 60),
('Basic 2', 'English Language', 'english', 'Oral Language', 'Conversation and Talking about Oneself, Family, People, Places, Customs, Events, Social/ Cultural Values and Manners and other Themes', 'B2.1.6.1', 'Use certain culturally acceptable language for communication', 'B2.1.6.1.1', 'Use appropriate greetings for special occasions', 'Revise daily greetings by having learners identify greeting times in the day: e.g. Morning-Good morning, Afternoon-Good afternoon, Evening-Good evening.; Discuss special occasions such as birthdays, anniversaries and festivals.; Discuss the correct greetings and responses on these occasions.; Let learners take turns to demonstrate greetings for special occasions and also practise the appropriate responses.', 70),
('Basic 2', 'English Language', 'english', 'Oral Language', 'Conversation and Talking about Oneself, Family, People, Places, Customs, Events, Social/ Cultural Values and Manners and other Themes', 'B2.1.6.1', 'Use certain culturally acceptable language for communication', 'B2.1.6.1.2', ' Put learners in groups to identify and talk about the parts of the drama (beginning, middle and ending)', 'Introduce the day’s topic and show pictures of activities at home.; Have learners think-pair-share the domestic activities.; Have learners talk about which of the events they like most and why they like them.; Have learners role-play some of the scenes. E.g. People engaged in domestic chores. People at table.', 80),
('Basic 2', 'English Language', 'english', 'Oral Language', 'Conversation and Talking about Oneself, Family, People, Places, Customs, Events, Social/ Cultural Values and Manners and other Themes', 'B2.1.6.1', 'Use certain culturally acceptable language for communication', 'B2.1.6.1.3', 'Talk about things and places in their homes', 'Ask learners to name things and places in their homes and say what happens at those places.; Show pictures of important places in their community, such as the chief''s palace, the market, the police station, etc. and have learners think-pair-share ideas or views with the person sitting next to them.; Put learners into groups to talk about their pictures.; Rotate the pictures until each group has had its turn to talk about all the pictures.', 90),
('Basic 2', 'English Language', 'english', 'Oral Language', 'Conversation and Talking about Oneself, Family, People, Places, Customs, Events, Social/ Cultural Values and Manners and other Themes', 'B2.1.6.1', 'Use certain culturally acceptable language for communication', 'B2.1.6.1.4', 'Use a wide variety of words to talk about manners', null, 100),
('Basic 2', 'English Language', 'english', 'Oral Language', 'Conversation and Talking about Oneself, Family, People, Places, Customs, Events, Social/ Cultural Values and Manners and other Themes', 'B2.1.6.2', 'Apply knowledge of language and communicative skills to participate in conversation', 'B2.1.6.2.1', 'Demonstrate turn-taking in conversations', 'Use the Community Circle Activity: Sit learners in horse-shoe formation.; Call individual learners to talk about what happened over the weekend. e. g. events, personal experiences, incidents, etc.; Let learners take turns to name and describe events of recent occurrence.; Discuss the importance of turn-taking in conversation: e.g. i. They talk after the last speaker has stopped. They talk when invited e.g. by the group leader.', 110),
('Basic 2', 'English Language', 'english', 'Oral Language', 'Conversation and Talking about Oneself, Family, People, Places, Customs, Events, Social/ Cultural Values and Manners and other Themes', 'B2.1.6.2', 'Apply knowledge of language and communicative skills to participate in conversation', 'B2.1.6.2.2', 'Ask and answer questions for clarifications about what other people say', 'Have learners recall the discussion on turn-taking in conversation and state the rules.; Encourage learners to ask and answer questions for clarification on what other learners have said.; Encourage appropriate language use during conversations.', 120),
('Basic 2', 'English Language', 'english', 'Oral Language', 'Listening Comprehension', 'B2.1.7.1', 'Use appropriate skills and strategies to process meaning from texts', 'B2.1.7.1.1', 'Listen to and interact actively with drama', 'Before Reading  Activate the previous knowledge of the learners by making them think pair and share with their friends.; Discuss illustrations accompanying the text.; Have them predict the content of the text.; Teach key vocabulary.; During Reading  Read the text aloud to learners. Pause often and have learners talk about the content of the text and answer simple questions based on the text.; After Reading  Have learners retell the story.; Let learners role-play the story.', 130),
('Basic 2', 'English Language', 'english', 'Oral Language', 'Listening Comprehension', 'B2.1.7.1', 'Use appropriate skills and strategies to process meaning from texts', 'B2.1.7.1.2', 'Recognise and relate the sequence of events (beginning, middle and end) in drama', 'Read a narrative text aloud to learners, following the procedure in', 140),
('Basic 2', 'English Language', 'english', 'Oral Language', 'Listening Comprehension', 'B2.1.7.1', 'Use appropriate skills and strategies to process meaning from texts', 'B2.1.7.1.3', 'Recognise and discuss events in a story (characters, settings, moral, etc.)', 'Read aloud a story to learners.; Have them identify and discuss (in pairs) the events in the story.; Have groups share their views with the whole class.', 150),
('Basic 2', 'English Language', 'english', 'Oral Language', 'Listening Comprehension', 'B2.1.7.1', 'Use appropriate skills and strategies to process meaning from texts', 'B2.1.7.1.4', 'Share facts from texts heard with a partner, groups or the teacher', 'Read an information text aloud to learners, using the KWL Strategy.  KWL Strategy: Before reading, have learners think-pair-share and talk about what they already know(K) about the title of the text. Have learners ask questions about what they want to know (W). While you read the text, pause often to give the children the chance to share what they have learned or answer the questions they have asked before reading.; After the reading, have learners share what they have learned.; Put learners in groups to share facts from the text heard.', 160),
('Basic 2', 'English Language', 'english', 'Oral Language', 'Asking and Answering Questions', 'B2.1.8.1', 'Demonstrate understanding in asking and answering questions', 'B2.1.8.1.1', 'Use appropriate pronunciation and intonation in asking and answering Wh', '– questions; Revise Yes/No questions and have learners answer some such question; Ask Wh questions and have learners answer them. e.g. Questions Answers Who took my pen? I did. Where is the book? It is on the table.; Ask them to say what is common to all the questions introduced by Wh words (what? when? why? how?). e.g. Why did you eat her food?; Guide learners to use appropriate pronunciation and intonation in asking and answering simple Wh – questions in pairs. One asks a Wh question and the other answers. They then reverse roles.; Let learners write out simple Wh – questions on their own.', 170),
('Basic 2', 'English Language', 'english', 'Oral Language', 'Giving and Responding to Commands, Instructions, Directions and Making Requests', 'B2.1.9.1', 'Demonstrate understanding in commands, instructions, directions and requests', 'B2.1.9.1.1', 'Give and respond to commands', 'Revise verbs (action words) by having learners identify the present form of verbs and use them in sentences, e.g. come, go, sit, etc. (action).; Have several learners obey commands such as ‘stand up’, ‘close the door’.; The teacher gives commands which the class/individuals promptly obey.; Have Learners role-play giving and responding to commands.', 180),
('Basic 2', 'English Language', 'english', 'Oral Language', 'Giving and Responding to Commands, Instructions, Directions and Making Requests', 'B2.1.9.1', 'Demonstrate understanding in commands, instructions, directions and requests', 'B2.1.9.1.2', 'Make and respond to polite requests', 'Let learners demonstrate in pairs how they ask for favours.; Discuss polite requests using examples. e. g. Can you hold the bag?; Discuss words used in polite requests. e.g. Please, could you…, do you mind….May I…; Have learners take turns to make and respond to polite requests using the word, “please”.; Discuss the importance of the word, “please”, in making requests.', 190),
('Basic 2', 'English Language', 'english', 'Oral Language', 'Giving and Responding to Commands, Instructions, Directions and Making Requests', 'B2.1.9.1', 'Demonstrate understanding in commands, instructions, directions and requests', 'B2.1.9.1.3', 'Respond to commands, instructions and requests', 'Introduce instructions by having learners respond to typical classroom instructions.; Create situations for learners to practise giving and responding to instruction.; Let learners role-play parents, teachers, prefects, learners giving and responding to instructions, etc. e. g. Instruction:; 1. Draw a circle in a square.; 2. Write the letter ‘A’ in the circle. Response', 200),
('Basic 2', 'English Language', 'english', 'Oral Language', 'Presentation', 'B2.1.10.1', 'Plan and present information and ideas for a variety of purposes', 'B2.1.10.1.1', 'Speak with confidence before different audience', 'Put learners in pairs to share their holiday plans with each other.; Have each person share his/her friend’s plans with the class.; Use probing questions to get learners give additional information: e.g. i. Where will he go first? ii. What will he be doing there? etc.', 210),
('Basic 2', 'English Language', 'english', 'Oral Language', 'Presentation', 'B2.1.10.1', 'Plan and present information and ideas for a variety of purposes', 'B2.1.10.1.2', 'Maintain appropriate posture, eye contact and use appropriate verbal and non-verbal cues to convey meaning', 'Model appropriate posture, eye contact and use verbal and non-verbal clues.; Let learners observe and do same.; Discuss when to use various postures, eye contact, verbal and non-verbal clues when talking to different people e.g. teacher, friend.; Have learners role-play how to maintain appropriate posture, verbal and non-verbal clues in communication. e.g. crossed arms and unblinking eye gaze to indicate disapproval.', 220),
('Basic 2', 'English Language', 'english', 'Reading', 'Phonics', 'B2.2.2.1', 'Connect sounds to letters and blend letters/syllables in order to read and write', 'B2.2.2.1.1', 'Blend syllables to produce words', 'Introduce the lesson with a recital that links the letters of the alphabet.; Have learners work in pairs, groups or individually to blend syllables to form meaningful words.; Use word families as a guide to help build on the words.', 230),
('Basic 2', 'English Language', 'english', 'Reading', 'Phonics', 'B2.2.2.1', 'Connect sounds to letters and blend letters/syllables in order to read and write', 'B2.2.2.1.2', 'Use the alphabetic knowledge to decode unknown words (', 'e. g. use beginning and ending consonants, consonant blends, consonant digraphs, vowel sounds, vowel digraphs and word patterns); Begin the lesson with an alphabet song, a rhyme or a poem.; Play games with the alphabet to decode unknown words, changing the position of the letters from beginning to middle and to ending.; Use demonstrations to show learners that whenever a letter moves (especially the consonant), it may still sound the same.; Have learners play alphabet games in pairs and groups.', 240),
('Basic 2', 'English Language', 'english', 'Reading', 'Phonics', 'B2.2.2.1', 'Connect sounds to letters and blend letters/syllables in order to read and write', 'B2.2.2.1.3', 'Use elements of structural analysis to decode unknown words', 'Have learners analyse the basic structure of unknown two-syllable words using specific indicators as a guide. Word Prefix root word Unclean un- Clean Word Suffix root word slowly -ly Slow; Let learners look at the different features of compound words.; Give learners the opportunity to work as teams/groups to come up with their own features, e. g. “class” and “room” will give “classroom”. Note: Consonant blends, digraphs, prefixes, suffixes, root words, compound words, etc.; Prefix; un-; Suffix; -ly', 250),
('Basic 2', 'English Language', 'english', 'Reading', 'Word Families-Rhyming Endings and Common Digraphs', 'B2.2.3.1', 'Employ knowledge of rhyming endings and common digraphs to enhance reading comprehension', 'B2.2.3.1.1', 'Use common rhyming/endings to decode simple words', 'Introduce learners to simple word formation by changing the beginning letter of words. e.g. pan, man, fan (You may use a phonic slide to give practice).; Have learners build on these rhyming endings.; In groups, let learners read out their words.; Have learners form sentences with these rhyming words.', 260),
('Basic 2', 'English Language', 'english', 'Reading', 'Word Families-Rhyming Endings and Common Digraphs', 'B2.2.3.1', 'Employ knowledge of rhyming endings and common digraphs to enhance reading comprehension', 'B2.2.3.1.2', 'Use words containing digraphs to make meaningful sentences', 'Introduce learners to simple digraphs as in; ch- church ph- photo sh - shirt; Have learners build as many words as possible from digraphs.; Have learners form meaningful sentences with the words.', 270),
('Basic 2', 'English Language', 'english', 'Reading', 'Vocabulary', 'B2.2.6.1', 'Understand word meanings and usages', 'B2.2.6.1.1', 'Read level-appropriate sight words, understand and use many of them in meaningful sentences', 'Introduce the selected sight words, one at a time, in context and write them on the board.; Start from the basic words they already know.; Have learners repeat the words aloud a number of times.; Write the words on the board.; Have learners read the words in order and at random.; Use think-pair-share to have learners form sentences with them.', 280),
('Basic 2', 'English Language', 'english', 'Reading', 'Vocabulary', 'B2.2.6.1', 'Understand word meanings and usages', 'B2.2.6.1.2', 'Use context clues to infer meanings of words', 'Create a story around a theme, using specific key words or vocabulary items you wish to teach.; Have learners use context to find the meaning of the key words.; Have learners make their own sentences using these key words.', 290),
('Basic 2', 'English Language', 'english', 'Reading', 'Vocabulary', 'B2.2.6.1', 'Understand word meanings and usages', 'B2.2.6.1.3', 'Show awareness that homonyms have different meanings in different contexts', 'Provide examples in contexts to help learners discover that homonyms have different meanings in different contexts. e.g. right and bat a. You are right. Raise your right hand. b. I saw a bat fly this morning. My mother bought a tennis bat for me.', 300),
('Basic 2', 'English Language', 'english', 'Reading', 'Vocabulary', 'B2.2.6.1', 'Understand word meanings and usages', 'B2.2.6.1.4', 'Use dictionaries and glossaries to clarify meaning of words', 'Introduce learners to the use of picture dictionaries and glossaries.; Have learners use guide words to find meaning of words used.; Have learners practise in pairs.', 310),
('Basic 2', 'English Language', 'english', 'Reading', 'Comprehension', 'B2.2.7.1', 'Understand and analyse texts read', 'B2.2.7.1.1', 'Use illustrations, text clues and context to make predictions during reading', 'Have learners use text features like title, illustrations and text clues to make meaning and inferences.; Have learners predict, brainstorm on the topic and have them read to confirm their predictions.; Have learners pause frequently during reading to make predictions to enhance comprehension.', 320),
('Basic 2', 'English Language', 'english', 'Reading', 'Comprehension', 'B2.2.7.1', 'Understand and analyse texts read', 'B2.2.7.1.2', 'Ask and answer factual and inferential questions about level- appropriate texts', 'Have learners read level-appropriate texts in pairs.; Guide learners to ask and answer simple inferential questions on the texts', 330),
('Basic 2', 'English Language', 'english', 'Reading', 'Comprehension', 'B2.2.7.1', 'Understand and analyse texts read', 'B2.2.7.1.3', 'Retell level-appropriate texts in own words', 'Revise some previous stories told.; Have learners retell a story using simple herring-bone strategies.', 340),
('Basic 2', 'English Language', 'english', 'Reading', 'Comprehension', 'B2.2.7.2', 'Use knowledge skills and techniques of reading to understand and interpret texts', 'B2.2.7.2.1', 'Demonstrate understanding of the purpose and features of information texts', 'Have learners read informational texts to identify their purpose and features through think-pair-share.', 350),
('Basic 2', 'English Language', 'english', 'Reading', 'Comprehension', 'B2.2.7.2', 'Use knowledge skills and techniques of reading to understand and interpret texts', 'B2.2.7.2.2', 'Describe events in a story', 'Have learners retell stories sequentially.; Have them identify and describe events in the stories.; Guide learners to unfold the events in a story sequentially.', 360),
('Basic 2', 'English Language', 'english', 'Reading', 'Comprehension', 'B2.2.7.2', 'Use knowledge skills and techniques of reading to understand and interpret texts', 'B2.2.7.2.3', 'Connect characters, ideas and information within a text', 'Have learners connect the ideas and information within a text to help construct meaning.', 370),
('Basic 2', 'English Language', 'english', 'Reading', 'Comprehension', 'B2.2.7.2', 'Use knowledge skills and techniques of reading to understand and interpret texts', 'B2.2.7.2.4', 'Read level-appropriate texts with little support', 'Have learners read different texts with little support from teacher. Gradually, scaffold to help learners read independently.', 380),
('Basic 2', 'English Language', 'english', 'Reading', 'Comprehension', 'B2.2.7.2', 'Use knowledge skills and techniques of reading to understand and interpret texts', 'B2.2.7.2.5', 'Use visualisation strategy (form mental images about texts) to enhance understanding of level-appropriate texts', 'Model using visualisation strategy to construct meaning from a text.; Through appropriate questions, guide learners to practise using visualisation strategy to construct meaning from texts. Note: visualisation strategy = forming mental image about texts.', 390),
('Basic 2', 'English Language', 'english', 'Reading', 'Fluency', 'B2.2.9.1', 'Read texts fluently', 'B2.2.9.1.1', 'Read texts/stories/passages with good pace, accuracy and expression', 'Model reading aloud with the focus on pace and expression.; Have learners, in group/pairs, read short texts aloud with the appropriate pace, accuracy and expression.', 400),
('Basic 2', 'English Language', 'english', 'Reading', 'Fluency', 'B2.2.9.1', 'Read texts fluently', 'B2.2.9.1.2', 'Read and recognise 120 sight words', 'Introduce learners to more sight words in context; Have them identify and use at least 120 sight-words Remember to focus on a few at a time.', 410),
('Basic 2', 'English Language', 'english', 'Reading', 'Fluency', 'B2.2.9.1', 'Read texts fluently', 'B2.2.9.1.3', 'Use contextual clues to confirm or self-correct pronunciation while reading aloud', 'Have learners use the context in which words are found to confirm or self- correct pronunciation of words while they read aloud.; Check intonation as they read to make meaning.', 420),
('Basic 2', 'English Language', 'english', 'Writing', 'Penmanship/Handwriting', 'B2.4.2.1', 'Copy and rewrite sentences correctly', 'B2.4.2.1.1', 'Copy sentences clearly', 'Demonstrate copying (sentences) on the board.; Let learners practise writing legibly and correctly on the board or into their books.; Have learners copy sentences from a book into their books.; Draw attention to inter and intra word spacing and alignment of letters, as well as clarity or writing.', 430),
('Basic 2', 'English Language', 'english', 'Writing', 'Writing Letters – Small and Capital', 'B2.4.3.1', 'Use general skills, strategies and knowledge of letter sounds to enable them write legibly and boldly', 'B2.4.3.1.1', 'Copy words in lower and upper case using correct spacing', 'Let learners write letters, both in upper and lower cases.; Copy words from learners’ reading book on the board as learners observe.; Let learners take turns to read out words from the list.; Draw attention to appropriate spelling and alignment of letters.; Let learners copy the words. Let them check correct spelling, formation of letters and spacing.', 440),
('Basic 2', 'English Language', 'english', 'Writing', 'Writing Letters – Small and Capital', 'B2.4.3.1', 'Use general skills, strategies and knowledge of letter sounds to enable them write legibly and boldly', 'B2.4.3.1.2', 'Use lower and upper case letters appropriately in words and simple sentences', 'Guide learners to choose level-appropriate topics. e. g. My Family, My Pet, My Friend, etc.; Let learners talk about the topic.; Write what learners say about the topic on the board. e. g. My family There are six people in my family. My father is a teacher. My mother is a nurse, etc.; Have learners read the sentences.; Re-write the sentences with wrong capitalisation and ask learners re-write them appropriately. e. g. my Father is a teacher.', 450),
('Basic 2', 'English Language', 'english', 'Writing', 'Writing Letters – Small and Capital', 'B2.4.3.1', 'Use general skills, strategies and knowledge of letter sounds to enable them write legibly and boldly', 'B2.4.3.1.3', 'Space words appropriately in sentences', 'Write the sentences on the board.; Let learners copy the sentences, paying attention to spacing of words in the sentence.; Encourage learners to display their work.', 460),
('Basic 2', 'English Language', 'english', 'Writing', 'Labelling Items', 'B2.4.4.1', 'Draw and label simple pictures', 'B2.4.4.1.1', 'Draw and label objects found in their environment', 'Take learners round to look at charts showing labelled objects.; Put learners into groups and ask them to choose an area in the environment where they will want to make a list of objects found there (e.g. home, market, shops etc.).; Let learners draw and label objects from the area studied by their group.; Help them to edit their work particularly spelling and spacing.; Let learners write their names under their work and post their charts on the walls of the classroom for peer review.', 470),
('Basic 2', 'English Language', 'english', 'Writing', 'Writing Simple Words and Sentences', 'B2.4.5.1', 'Use knowledge of grammar and vocabulary to write words and sentences correctly. CONT’D CONTENT STANDARDS', 'B2.4.5.1.1', 'Write simple sentences to express feelings', 'Put learners in groups to share their feelings.; Let each one write, at least, one sentence to express a feeling, e.g. "I am happy."', 480),
('Basic 2', 'English Language', 'english', 'Writing', 'Writing Simple Words and Sentences', 'B2.4.5.1', 'Use knowledge of grammar and vocabulary to write words and sentences correctly. CONT’D CONTENT STANDARDS', 'B2.4.5.1.2', 'Write simple and meaningful sentences on objects found in the environment', 'Take learners out on a field-trip outside the school to observe things.; Discuss the trip and write their observations in simple sentences on the board. e.g. i. There is a blue house near the school. ii. The house is small. iii. I saw a big bus. iv. The bus has a driver. v. A big shop is near the school. vi. Taxi cabs are on the road. etc.; Put learners into groups to write simple sentences about the objects and places found in the environment.; Encourage each group to add pictures to their sentences.; Publish their work on the walls and encourage gallery walk.', 490),
('Basic 2', 'English Language', 'english', 'Writing', 'Writing Simple Words and Sentences', 'B2.4.5.1', 'Use knowledge of grammar and vocabulary to write words and sentences correctly. CONT’D CONTENT STANDARDS', 'B2.4.5.1.3', 'Draw a picture and write at least a sentence to share an opinion', 'Show pictures of ‘smiley/images on your phone or card’, e.g. smiling, angry, indifferent or frightened faces, etc.; Let learners study the pictures and interpret them.; Let learners, in pairs, discuss their opinions. Note: The learner’s opinion is very important and whatever interpretation learners give must be accepted.', 500),
('Basic 2', 'English Language', 'english', 'Writing', 'Controlled Writing', 'B2.4.7.1', 'Write simple compositions', 'B2.4.7.1.1', 'Write or copy correct sentences from substitution tables', 'Have a simple 3-4 column substitution table on the board. e.g. I Sing S c h o o l We Play at Home The Boys Read the park; Have learners identify the words that make up the table.; With an example, let learners form sentences from the substitution table.; Have learners read out their sentences and write down their sentences in their books.', 510),
('Basic 2', 'English Language', 'english', 'Writing', 'Controlled Writing', 'B2.4.7.1', 'Write simple compositions', 'B2.4.7.1.2', 'Match parts of sentences to compose meaningful texts', 'Let learners talk about the topic (My House) by using descriptive words in sentences.; Write the sentences on the board. e.g. i. My house is big. ii. The walls are blue. iii. The house has many windows. iv. The windows are big. v. The doors and windows are blue.;  Write the sentences and break each into two parts for learners to match the beginning with their correct endings. e. g. My house The walls many windows. The windows is big. There are are blue.  Encourage learners to do peer editing.', 520),
('Basic 2', 'English Language', 'english', 'Writing', 'Controlled Writing', 'B2.4.7.2', 'Matching parts of sentences to composition', 'B2.4.7.2.1', 'Re-arrange jumbled sentences logically', 'Tell/Read an interesting story to learners.; Let them retell the story.; Jumble up the sentences making up the story and ask learners to re-arrange them.', 530),
('Basic 2', 'English Language', 'english', 'Writing', 'Guided Composition', 'B2.4.8.1', 'Compose short paragraphs through answering questions', 'B2.4.8.1.1', 'Develop two coherent paragraphs on one idea or concepts using leading questions', 'Write selected topics on the board, e.g. “Myself”.; Teacher and learners brainstorm to generate ideas about the topic.; Put learners in groups and ask leading questions to guide them develop the ideas generated into one or two paragraphs.', 540),
('Basic 2', 'English Language', 'english', 'Writing', 'Narrative Writing', 'B2.4.10.1', 'Narrate situations, express feelings and convey point of view about the real or fictional world', 'B2.4.10.1.1', 'Write about real or imagined experiences or events using the process approach', 'Ask learners simple questions on their daily routines.; Let learners brainstorm and choose a topic for the day. e. g."A visit to the market" or "A visit to the beach"; Using questions, assist learners to write a paragraph or two about their experiences. e. g. i. What is the name of the market? ii. Where is the market? iii. What did you buy from the market?; Let learners write a short paragraph and paste it on the notice board. Note: Learners may create imaginary experiences and write about them.', 550),
('Basic 2', 'English Language', 'english', 'Writing', 'Descriptive Writing', 'B2.4.12.1', 'Demonstrate knowledge of description in writing', 'B2.4.12.1.1', 'Use simple sentences to describe feelings', 'Let learners name and describe common objects using adjectives.; Let learners name various objects in the classroom.; Explain what they have to do.; Demonstrate the activity by describing an object in 3-5 sentences. Write the sentences on the board.; Let individuals choose objects and describe them orally and then in writing.', 560),
('Basic 2', 'English Language', 'english', 'Using Writing Conventions/Grammar Usage', 'Using Capitalisation', 'B2.5.1.1', 'Apply knowledge of capitalisation in writing', 'B2.5.1.1.1', 'Use capital letter to write names of particular places and days of the week', 'Provide a sample text and have learners identify names of particular places and days of the week.; Have them compare the initial letters of these names and other common names and share their observations with the class.; Give learners a text with names of particular places and days of the week, beginning with small letters. Let learners rewrite the text, beginning the names of particular places and days of the week, with capital letters.', 570),
('Basic 2', 'English Language', 'english', 'Using Writing Conventions/Grammar Usage', 'Using Capitalisation', 'B2.5.1.1', 'Apply knowledge of capitalisation in writing', 'B2.5.1.1.2', 'Use capital letters to begin the first words of sentences', 'Assist learners to begin sentences with capital letters. For example: i. Kofi is a good boy. ii. The house is beautiful.', 580),
('Basic 2', 'English Language', 'english', 'Using Writing Conventions/Grammar Usage', 'Using Punctuation', 'B2.5.2.1', 'Apply knowledge of punctuation in written communication', 'B2.5.2.1.1', 'Use full stops at the end of sentences and question marks at the end of questions', 'Have learners look at sentences in their class readers to observe how they begin and end.; Demonstrate placing a full stop (.) at the end of a sentence.; Let learners copy and punctuate sentences with full stop.; Present the question mark similarly.', 590),
('Basic 2', 'English Language', 'english', 'Using Writing Conventions/Grammar Usage', 'Using Action Words', 'B2.5.4.1', 'Apply knowledge of action words in communication', 'B2.5.4.1.1', 'Use the simple present tense to express habitual actions (simple truths, interest, feelings and opinions)', 'Tell learners some of the things you do daily in short and simple sentences. e.g. I read stories everyday.; Create situations for learners to use the structure. e.g. i. simple truths –Lemons are sour. ii. interest – I like playing football. iii. feelings – I am happy. iv. opinions – He is a good teacher.; Introduce drills for learners to have practice.; Put learners into small groups to discuss given topics, using the structures.', 600),
('Basic 2', 'English Language', 'english', 'Using Writing Conventions/Grammar Usage', 'Using Adjectives', 'B2.5.5.1', 'Apply knowledge of adjectives in communication', 'B2.5.5.1.1', 'Identify and use simple sentences to describe the weather and show quantity and position or order of people and things', 'Use appropriate texts to help learners to describe the weather and show quantity and position or order of people and things, e.g: weather - It is cold. quantity – I have two pens. position or order of people and things – She is on the first row.', 610),
('Basic 2', 'English Language', 'english', 'Using Writing Conventions/Grammar Usage', 'Using Simple Preposition', 'B2.5.7.1', 'Understand and identify the use of prepositions', 'B2.5.7.1.1', 'Identify prepositions in sentences to indicate days, dates and places', 'Let learners use the preposition in, on, in context. e.g. i. I saw a bird on Monday. ii. I have a test on 1st May, 2018. iii. They are in the classroom.', 620),
('Basic 2', 'English Language', 'english', 'Using Writing Conventions/Grammar Usage', 'Using Simple Preposition', 'B2.5.7.1', 'Understand and identify the use of prepositions', 'B2.5.7.1.2', 'Use prepositions to form simple sentences to indicate position and time', 'Provide a short passage containing prepositions that indicate position and time.;  Let learners identify the prepositions. e. g. i. Esi sat on a chair in the room. ii. The other pupils stood on the veranda. iii. The teacher went to the classroom at night.', 630),
('Basic 2', 'English Language', 'english', 'Using Writing Conventions/Grammar Usage', 'Using Simple and Compound Sentences', 'B2.5.9.1', 'Understand simple sentences in writing', 'B2.5.9.1.1', 'Identify the structure of simple sentences', 'Use context to help learners identify the structure of simple sentences. Yaa came. (Name) + (Doing word) Musa ate.', 640),
('Basic 2', 'English Language', 'english', 'Using Writing Conventions/Grammar Usage', 'Using Simple and Compound Sentences', 'B2.5.9.1', 'Understand simple sentences in writing', 'B2.5.9.1.2', 'Identify nouns and verbs in simple sentences', 'Use questions and samples to learners to identify nouns and verbs in the structure of simple sentences. e. g. i. Ofori danced. (Who danced? What did Ofori do?) ii. Ama laughed', 650),
('Basic 2', 'English Language', 'english', 'Using Writing Conventions/Grammar Usage', 'Spelling', 'B2.5.10.1', 'Use phonics knowledge to spell words', 'B2.5.10.1.1', 'Use phonics knowledge to spell words with irregular phonic letter pattern', 'Have learners play the pick and spell game to spell phonetically irregular words. e. g. the, face; Have learners use these words in oral and written sentences.;  Provide sentences with blank spaces for learners to fill in the blanks using the words they have learnt to spell. e. g. i. This is my-------.', 660),
('Basic 2', 'English Language', 'english', 'Extensive Reading', 'Building The Love And Culture Of Reading', 'B2.6.1.1', 'Read widely for pleasure and to demonstrate independent reading and learning in the literary area', 'B2.6.1.1.1', 'Read a variety of age and level-appropriate books and texts from print and non-print', 'Use the Author’s chair to introduce the reading/ library time.; Have a variety of age and level-appropriate books for learners to make a choice.; Introduce narratives, pop-up and flip-the-page texts to learners.; Introduce e-books to learners, if available.; For each reading session, guide learners to select books.', 670),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Songs', 'B2.1.1.1', 'Demonstrate an understanding of types of work and play songs and learn them', 'B2.1.1.1.1', 'Sing work and play songs and discuss their importance', 'Revise traditional occupations with learners.; Lead learners to sing a popular work song.; Introduce a new work and its song. Teach learners the song.; Let learners sing the song in groups and individually.; Introduce a new play and its song.; Lead learners to discuss how the play is performed and the song associated with the play.; Let learners sing a popular play song as a group and individually.; Discuss the importance of work and play songs with learners. E.g. Work songs: – reduce fatigue, removes boredom, provides enjoyment, allows systematic work, inspires fellow workers to work harder, builds vocabulary etc. Play songs – creates unity, develops one’s creativity, provides enjoyment and inspiration.', 10),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Songs', 'B2.1.1.1', 'Demonstrate an understanding of types of work and play songs and learn them', 'B2.1.1.1.2', 'Relate types of play songs to everyday activities in their environment', 'Show a picture of a playground to learners.; Lead learners to talk about the picture.; Discuss the various traditional plays in the community with learners.; Pick one traditional play and teach how it is performed.; Teach the song that is sung when playing the game.; Let learners sing song again.; Put learners into groups to perform the play. E.g. Moonlight play songs etc.', 20),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Songs', 'B2.1.1.1', 'Demonstrate an understanding of types of work and play songs and learn them', 'B2.1.1.1.3', 'Relate types of work songs to everyday activities in their environment', 'Let learners sing a familiar traditional song.; Show a picture of someone weaving to learners.; Discuss the picture with learners.; Discuss the various traditional occupations in the community with learners.; Pick a particular song of a traditional occupation and teach learners the song that is associated with that occupation.; Let learners sing the song in groups and then individually.; Lead learners to recognise various works and their corresponding songs. E.g. Fishing, kente weaving, farming, etc.', 30),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Rhymes', 'B2.1.2.1', 'Demonstrate knowledge of some selected rhymes with their correct rhythms by listening attentively', 'B2.1.2.1.1', 'Explore rhymes with correct rhythm', 'Ask learners to sing a popular traditional occupational song.; Explore a rhyme.; Lead learners to learn how to explore the rhyme with correct rhythm.; Lead learners to explore the rhyme with gestures.; Call learners individually to explore the rhyme with correct rhythm.', 40),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Rhymes', 'B2.1.2.1', 'Demonstrate knowledge of some selected rhymes with their correct rhythms by listening attentively', 'B2.1.2.1.2', 'Explore rhymes with problematic sounds', 'Let learners explore a popular rhyme they know.; Explore a rhyme made up of sounds that pose problems to learners.; Teach learners how the rhyme is explored.; Let learners explore rhymes with problematic sounds in groups and in pairs.; Lead learners to explore the rhyme with gestures.; Let learners explore the rhyme individually with gestures.; NB: Please take note of the sounds and correct learners where n ecessary.', 50),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Listening and Story Telling', 'B2.1.4.1', 'Exhibit knowledge of listening to and retelling simple stories', 'B2.1.4.1.1', 'Retell part of a story', 'Tell or show a clip of an interesting story of not more than ten minutes long to learners.; Discuss the clip with learners.; Ask learners to retell it.', 60),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Listening and Story Telling', 'B2.1.4.1', 'Exhibit knowledge of listening to and retelling simple stories', 'B2.1.4.1.2', 'Recognise the morals/values in a story', 'Tell an interesting story.; Show video of an interesting story.; Discuss with learners the morals/values in the story they have heard or watched.', 70),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Listening and Story Telling', 'B2.1.4.1', 'Exhibit knowledge of listening to and retelling simple stories', 'B2.1.4.1.3', 'Dramatise part of the story', 'Let learners watch the video again.; Assign roles to them and let them dramatise the first three scenes.; Direct learners to dramatise the story.', 80),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Dramatisation and Role Play', 'B2.1.5.1', 'Perform a sketch of a story heard or told', 'B2.1.5.1.1', 'Dramatise a story a story and discuss key issues and lessons in the sketch', 'Tell or read an interesting story to learners.; Lead learners to discuss the story in groups.; Call the groups to tell the class their thoughts on the story.; Assign roles to learners.; Direct learners to dramatise the story.; Lead learners through discussions to recognise key issues and lessons in the story.', 90),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Conversation', 'B2.1.6.1', 'Exhibit knowledge of greeting and responding appropriately according to the time of day and occasion', 'B2.1.6.1.1', 'Discuss occasions to greet and talk about the importance of greetings', 'Ask learners to tell you what they do when they meet a teacher in school in the morning.; Demonstrate different greeting to learners.; Lead learners through discussions to recognise the various occasions to greet.; Pick about three occasions and discuss their greetings with learners. E.g. Festivals, birth, death, etc.; Lead learners to discuss the values of greetings. E.g.to show respect, politeness, concern, friendliness, phatic communion, etc.', 100),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Conversation', 'B2.1.6.1', 'Exhibit knowledge of greeting and responding appropriately according to the time of day and occasion', 'B2.1.6.1.2', 'Discuss the greetings associated with different occasions', 'Let learners mention some occasions they know.; Write the occasions on the board.; Write the various occasional greetings on the board and lead learners to connect the occasions with the greetings.; Allow learners to practice the greetings in pairs.', 110),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Talking about Oneself, Family, People and Places', 'B2.1.7.1', 'Narrate personal experiences at events', 'B2.1.7.1.1', 'Narrate an experience at the market', 'Show a picture of a market to learners.; Discuss the picture with learners.; Discuss what goes on at the market with learners.; Ask learners to tell their experiences at the market.', 120),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Talking about Oneself, Family, People and Places', 'B2.1.7.1', 'Narrate personal experiences at events', 'B2.1.7.1.2', 'Narrate an experience at the hospital', 'Show a picture of a hospital to learners.; Discuss the picture with learners.; Discuss what goes on at the hospital with learners.; Ask learners to tell their experience at the hospital.', 130),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Talking about Oneself, Family, People and Places', 'B2.1.7.1', 'Narrate personal experiences at events', 'B2.1.7.1.3', 'Narrate experiences at school', 'Let learners talk about their homes.; Show a picture of a school to learners.; Let learners talk about the picture.; Discuss what goes on at the school with learners.; Ask learners to tell their experiences at school.', 140),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Talking about Oneself, Family, People and Places', 'B2.1.7.1', 'Narrate personal experiences at events', 'B2.1.7.1.4', 'Narrate experiences at the church/mosque, palace etc', 'Show a picture of a palace to learners/ Visit a palace/church.; Discuss what goes on at the church or palace with learners.; Ask learners to tell their experiences at the church or palace.', 150),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Listening Comprehension', 'B2.1.8.1', 'Show an understanding of answering questions from a passage', 'B2.1.8.1.1', 'Recount what a story is about and answer simple questions on the story', 'Revise the lesson on learners’ experiences at the market, school and palace.; Tell an interesting story or show a movie of a short story.; Lead learners to discuss the story or movie.; Let learners tell what the story is about.; Ask questions based on the story for learners to answer. E.g.: What is the story about? Mention a character in the story. Where did the story take place?', 160),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Listening Comprehension', 'B2.1.8.1', 'Show an understanding of answering questions from a passage', 'B2.1.8.1.2', 'Explain the meaning of some key words in the story', 'Write some key words of the story you told.; Let learners discuss the meaning of some of the key words contextually.', 170),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Asking and Answering Questions', 'B2.1.9.1', 'Demonstrate knowledge on understanding and answering of questions correctly using question words', 'B2.1.9.1.1', 'Recognise and use the question words, “what”, “who”, “where”, “when.”', 'Write some questions on a flashcard using the question words “what”, “who”, “where”, “when” and show them to learners.; Lead learners to read the questions.; Let learners form their own questions using the question words under discussion.; Assist learners to recognise when to use question words/tags ‘what’ and ‘who,’” where” and” when”.; E.g. What is your age? Who is your mother? Where is your teacher? When will you come?', 180),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Asking and Answering Questions', 'B2.1.9.1', 'Demonstrate knowledge on understanding and answering of questions correctly using question words', 'B2.1.9.1.2', 'Recognise when to use the question word, “how.”', 'Write some questions on flashcards using the question word “how” and show them to learners.; Lead learners to read the questions.; Let learners form their own questions using the question word under discussion.; Assist learners to understand when to use the question word “How”', 190),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Asking and Answering Questions', 'B2.1.9.1', 'Demonstrate knowledge on understanding and answering of questions correctly using question words', 'B2.1.9.1.3', 'Recognise and use the question word, “why.”', 'Write some questions on flashcards and show them to learners.; Lead learners to read the questions.; Let learners form their own questions using the question word under discussion.; Assist learners to recognise when to use the question word “why”.; Let learners form their own questions using the question word under discussion.', 200),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Asking and Answering Questions', 'B2.1.9.1', 'Demonstrate knowledge on understanding and answering of questions correctly using question words', 'B2.1.9.1.4', 'Answer questions on, ‘who”, “what”, “where” and “when.”', 'Write questions on flashcards and show them to learners.; Call learners individually to read the questions.; Let learners understand when to use the question words “who,” “what,” “where” and “when”.; Ask learners questions using the question words under discussion and call them to answer the questions (correct learners where necessary). E.g. What is your age? Who is your mother? Where is your teacher? When will you come?', 210),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Giving and Following Commands/Instructions', 'B2.1.10.1', 'Exhibit knowledge of understanding and carrying out simple instructions and commands', 'B2.1.10.1.1', 'Say what a command is', 'Revise the lesson on greetings with learners.; Demonstrate command and respond with a learner in class.; Discuss what a command is with learners.', 220),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Giving and Following Commands/Instructions', 'B2.1.10.1', 'Exhibit knowledge of understanding and carrying out simple instructions and commands', 'B2.1.10.1.2', 'Respond to six to seven commands', 'Call learners in pairs and let one issue a command for the other to respond to the command.; E.g. Stand up! Sit down! Keep quiet!', 230),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Giving and Following Commands/Instructions', 'B2.1.10.1', 'Exhibit knowledge of understanding and carrying out simple instructions and commands', 'B2.1.10.1.3', 'Discuss the importance of commands and instructions', 'Write some commands on the board and lead learners to read them.; Let learners read the command as a group and then individually.; Call a learner to come out and issue a command for the class to respond.; Lead learners to recognise the importance of commands and instructions. E.g. to get work done on time; to draw your attention; for s afety, peace, success, etc.', 240),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Presentation', 'B2.1.11.1', 'Demonstrate knowledge on the days of the week and say the time by the hour and half hour', 'B2.1.11.1.1', 'Say the time by the hour', 'Discuss the various times of the day with learners, e.g., morning, afternoon and evening.; Show a clock to learners and ask learners to tell you what the clock is used for.; Use the clock to assist learners to tell the time by the hour. E.g. The time is 3 o’clock.', 250),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Presentation', 'B2.1.11.1', 'Demonstrate knowledge on the days of the week and say the time by the hour and half hour', 'B2.1.11.1.2', 'Say the time by half hour', 'Use the clock to assist learners to tell time by half hour. E.g. The time is 2:30pm. The time is 30 minutes past 4 o’clock.', 260),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Presentation', 'B2.1.11.1', 'Demonstrate knowledge on the days of the week and say the time by the hour and half hour', 'B2.1.11.1.3', 'Recognise the days of the week in chronological order', 'Revise the lesson on telling the time with learners.; Write the days of the week on the board and lead learners to mention them.; Call learners to mention the names of the days of the week individually.; Lead learners to mention and arrange the names of the days of the week in a chronological order. E.g. Monday, Tuesday, etc.', 270),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Phonological and Phonemic Awareness', 'B2.2.3.1', 'Demonstrate knowledge of hearing, recognising and differentiating sounds in spoken words', 'B2.2.3.1.1', 'Recognise and create words with the same sounds - initial and final position', 'Let learners explore a rhyme.; Write some words on the board.; Lead learners to mention the words.; Call learners to mention the words individually.; Assist learners through discussion to recognise and create words with the same sounds in word initial and final positions.', 280),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Phonics (Blend and Connect Sounds)', 'B2.2.4.1', 'Show an understanding of connecting sounds to letters and blending letters into syllables in order to read', 'B2.2.4.1.1', 'Blend syllables to produce simple words', 'Let learners explore a rhyme.; Write some syllables on a manila card and show it to learners.; Lead learners to read the syllables.; Lead learners to blend syllables to produce simple words.', 290),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Phonics (Blend and Connect Sounds)', 'B2.2.4.1', 'Show an understanding of connecting sounds to letters and blending letters into syllables in order to read', 'B2.2.4.1.2', 'Use alphabetic knowledge to decode words', 'Revise the letters of the alphabet with learners.; Write some words on a manila card and assist learners to use alphabetic knowledge to decode the words.', 300),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Phonics (Blend and Connect Sounds)', 'B2.2.4.1', 'Show an understanding of connecting sounds to letters and blending letters into syllables in order to read', 'B2.2.4.1.3', 'Read simple short sentences', 'Write some simple sentences on the board.; Lead learners to read the sentences.; Call learners to read the simple sentences on the board as a group.; Let learners read the sentences individually and correct them where necessary.', 310),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Phonics (Blend and Connect Sounds)', 'B2.2.4.2', 'Recognise and read words with identical sounds', 'B2.2.4.2.1', 'Listen and say words with identical sounds from simple sentences', 'Write some words on the board and lead learners to read the words.; Lead learners to recognise the words with identical sounds among the words you have written.; Let learners listen to and say words with identical sounds from simple sentences.', 320),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Phonics (Blend and Connect Sounds)', 'B2.2.4.2', 'Recognise and read words with identical sounds', 'B2.2.4.2.2', 'Read simple poems and recognise rhyming words', 'Let learners explore a rhyme.; Write a simple poem on the board.; Lead learners to explore the poem.; Call learners to explore the poem individually.; Lead learners to explore the poem again with gestures.; Assist learners to read simple poems and lead learners to recognise rhyming words.', 330),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Phonics (Blend and Connect Sounds)', 'B2.2.4.2', 'Recognise and read words with identical sounds', 'B2.2.4.2.3', 'Recognise diagraphs from letters of the alphabet', 'Let learners explore a poem.; Write some diagraphs and the letters of the alphabet on the board.; Let learners say the letters of the alphabet.; Assist learners to recognise diagraphs from the letters of the alphabet.', 340),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Phonics (Blend and Connect Sounds)', 'B2.2.4.2', 'Recognise and read words with identical sounds', 'B2.2.4.2.4', 'Read three-syllable words', 'Let learners say the letters of the alphabet as a group and individually.; Write some three-syllable words on the board and lead learners to read them.; Call learners one by one to read the words.', 350),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Vocabulary', 'B2.2.5.1', 'Show an understanding of recognising and reading about things in their environment', 'B2.2.5.1.1', 'Recognise sounds that make up words', 'Revise sounds with learners.; Write some words on the board and lead learners to read them.; Assist learners to recognise sounds that make up the words.', 360),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Vocabulary', 'B2.2.5.1', 'Show an understanding of recognising and reading about things in their environment', 'B2.2.5.1.2', 'Make picture dictionaries', 'Let learners cut pictures of different objects and arrange them in alphabetical order in their books.; Lead learners to write the names of the images in the pictures under them.', 370),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Vocabulary', 'B2.2.5.1', 'Show an understanding of recognising and reading about things in their environment', 'B2.2.5.1.3', 'Match action words with corresponding pictures', 'Display a picture showing actions of various kinds.; Write the actions on the board and lead learners to match the action words with the pictures.; Allow learners to do some actions.', 380),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Comprehension', 'B2.2.6.1', 'Exhibit knowledge of answering questions based on texts presented', 'B2.2.6.1.1', 'Interpret meaning of pictures', 'Show learners a picture story.; Lead learners through discussions to interpret the pictures.', 390),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Comprehension', 'B2.2.6.1', 'Exhibit knowledge of answering questions based on texts presented', 'B2.2.6.1.2', 'Make predictions of what will happen next', 'Discuss the first picture in a story book with learners.; Lead learners to brainstorm on what they think would happen in the next pages or pictures in the story.; Continue to discuss the other pictures with learners making learners keep predicting what they think will happen next.', 400),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Comprehension', 'B2.2.6.1', 'Exhibit knowledge of answering questions based on texts presented', 'B2.2.6.1.3', 'Recognise the titles and authors of books', 'Show books to learners.; Help learners recognise titles and authors of the books through discussion.', 410),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Comprehension', 'B2.2.6.1', 'Exhibit knowledge of answering questions based on texts presented', 'B2.2.6.1.4', 'Explain simple vocabulary', 'Write some simple words on a card.; Let learners pick the cards and mention the words written on it.; Pick the cards at random and show it to learners and ask them to mention the words on the card.; Lead learners to find the meaning of the words.', 420),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Comprehension', 'B2.2.6.1', 'Exhibit knowledge of answering questions based on texts presented', 'B2.2.6.1.5', 'Answer simple questions', 'Read the first paragraph of a short passage to learners aloud.; Pause and ask them questions based on the paragraph read.; Continue reading and asking questions intermittently until the whole passage i s read.', 430),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Silent Reading', 'B2.2.7.1', 'Demonstrate knowledge on reading for comprehension', 'B2.2.7.1.1', 'Read four to five sentences consisting of eight to ten words', 'Give learners story books consisting of four to five sentences.; Lead learners to read the sentences in the story books.; Call learners to read the sentences on individual bases.; Let learners tell what they understand from what they have read.', 440),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Fluency', 'B2.2.8.1', 'Exhibit knowledge by reading with minimal mistakes', 'B2.2.8.1.1', 'Read aloud words and sentences of about four to five words using correct pronunciation', 'Share Readers or reading books with sentences of four to five words to learners.; Let learners scan through the book to look for new vocabulary.; Lead learners to mention the words.; Lead the class to read and call learners to read as well using correct pronunciation.', 450),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Writing', 'Penmanship/Handwriting', 'B2.3.1.1', 'Understand how to copy sentences clearly; write letters or words and practice saying those that give them difficulty', 'B2.3.1.1.1', 'Write letters clearly and boldly', 'Write the letters of the alphabet boldly on the board.; Lead learners to say the letters of the alphabet aloud.; Call learners individually to say the letters of the alphabet aloud.; Assist learners to write letters boldly and clearly.', 460),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Writing', 'Penmanship/Handwriting', 'B2.3.1.1', 'Understand how to copy sentences clearly; write letters or words and practice saying those that give them difficulty', 'B2.3.1.1.2', 'Write words clearly and boldly', 'Lead learners to say the letters of the alphabet aloud.; Call learners individually to say the letters of the alphabet aloud.; Write short words boldly on the board.; Lead learners to mention the words aloud.; Call learners individually to mention the words.; Assist learners to write the words boldly and clearly.', 470),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Writing', 'Penmanship/Handwriting', 'B2.3.1.1', 'Understand how to copy sentences clearly; write letters or words and practice saying those that give them difficulty', 'B2.3.1.1.3', 'Copy simple sentences clearly and boldly', 'Write simple sentences boldly on the board.; Lead learners to read the sentences.; Assist learners to write the sentences boldly and clearly.', 480),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Writing', 'Penmanship/Handwriting', 'B2.3.1.1', 'Understand how to copy sentences clearly; write letters or words and practice saying those that give them difficulty', 'B2.3.1.1.4', 'Practise saying letters or words that present difficulty to them', 'Write the letters of the alphabet and simple words on the board.; Lead learners to say the words and the letters of the alphabet and call learners to say them one after the other.; Let learners keep practicing those they have difficulty with.', 490),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Writing', 'Writing Simple Words/Names of People and Places (Proper Nouns) Labelling Items in the Environment/Classroom', 'B2.3.3.1', 'Practise saying words which they have difficulty in pronouncing. B2.3.3.2.1: Show understanding of items in the environment/ classroom', 'B2.3.3.1.1', 'Write and practise saying letters they have difficulty with', 'Write the letters of the alphabet and simple words on the board.; Lead learners to say the words and the letters of the alphabet and call learners to say them one after the other.; Let learners keep practicing those they have difficulty with.', 500),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Writing', 'Writing Simple Words/Names of People and Places (Proper Nouns) Labelling Items in the Environment/Classroom', 'B2.3.3.1', 'Practise saying words which they have difficulty in pronouncing. B2.3.3.2.1: Show understanding of items in the environment/ classroom', 'B2.3.3.1.2', 'Write and practice saying words they have difficulty with', 'Write the letters of the alphabet and simple words on the board and lead learners to say them.; Call learners to say them one after the other.; Let learners keep practicing those they have difficulty with.', 510),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Writing', 'Writing Simple Words/Names of People and Places (Proper Nouns) Labelling Items in the Environment/Classroom', 'B2.3.3.2', 'Practise saying words which they have difficulty in pronouncing. B2.3.3.2.1: Show understanding of items in the environment/ classroom', 'B2.3.3.2.1', 'Label and mention items in the classroom and in the school', 'Draw some items in the home and school on a manila card.; Let learners use their knowledge on sorting to sort the items into those found in the home and in the school.; Lead learners to label and mention items in the classroom and in the school.; Point to some items in the class and let learners mention the names and draw and label them.', 520),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Writing', 'Copying/Writing Simple Sentences with Correct Spacing', 'B2.3.4.1', 'Exhibit knowledge of writing simple sentences with correct word spacing', 'B2.3.4.1.1', 'Write short sentences with correct spacing about objects and pets', 'Draw objects and pets on a manila card and display it to learners.; Lead learners through discussion to mention the things drawn on the card.; Use the words to form simple sentences and lead learners to read them aloud.; Let learners read the simple sentences aloud individually.; Let learners write simple sentences with correct spacing about objects and pets.', 530),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Writing', 'Copying/Writing Simple Sentences with Correct Spacing', 'B2.3.4.1', 'Exhibit knowledge of writing simple sentences with correct word spacing', 'B2.3.4.1.2', 'Write short sentences with correct spacing about people and places', 'Show a picture of people and places to learners.; Lead learners to discuss the picture.; Use the names of the people and places in the picture to form simple sentences.; Lead learners to read the sentences aloud.; Let learners read the sentences aloud on their own.; Call individual learners to read the sentences.; Let learners form their own sentences using the names of people and places in the picture.; Let learners write short sentences with correct spacing about the people and places in the drawing.', 540),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/Usage', 'Integrating Grammar in Written Language (Capitalization)', 'B2.5.1.1', 'Exhibit knowledge of using capital letters', 'B2.5.1.1.1', 'Write proper nouns with capital letters', 'Let learners say the letters of the alphabet as a group.; Call individual learners to say the letters of the alphabet.; Write names of persons and places on manila card in capital letters.; Lead learners to read the names and discuss the names with them.; Call learners to read the names on their own.; Let learners use capital letters to write the proper nouns.', 550),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/Usage', 'Integrating Grammar in Written Language (Capitalization)', 'B2.5.1.1', 'Exhibit knowledge of using capital letters', 'B2.5.1.1.2', 'Use capital letters to start sentences', 'Revise the lesson on the letters of the alphabet with learners.; Write simple sentences on the board and ask learners to recognise the first letter in every sentence.; Lead learners to read the simple sentences aloud.; Call individual learners to read the sentences.; Let learners write the sentences making sure that each sentence is started with a capital letter.', 560),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/Usage', 'Integrating Grammar in Written Language (Capitalization)', 'B2.5.1.1', 'Exhibit knowledge of using capital letters', 'B2.5.1.1.3', 'Use capital letters after full stops', 'Revise the lesson on the letters of the alphabet with learners.; Write simple sentences on the board and ask learners to recognise the first letter in each sentence.; Lead learners to read the simple sentences aloud.; Call individual learners to read the sentences.; Let learners write the sentences making sure that each sentence is dotted at the end, and another started with a capital letter.', 570),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/Usage', 'Integrating Grammar in Written Language (Punctuation)', 'B2.5.2.1', 'Show an understanding of the use of full stops', 'B2.5.2.1.1', 'Know what the full stop and the comma are', 'Let learners demonstrate the morning greeting.; Write simple sentences that are well punctuated on a card (the sentence should have full stops and comma).; Lead learners to read the sentences aloud.; Call learners to read aloud the sentences individually.; Discus what a full stop is with learners.; Discuss what a comma is with learners.; Assist learners to tell what full stop and commas are.', 580),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/Usage', 'Integrating Grammar in Written Language (Use of Action Words)', 'B2.5.3.1', 'Show an understanding of writing action words', 'B2.5.3.1.1', 'Write two-letter present tense action words', 'Give a command for learners to respond.; Call learners in pairs to demonstrate a command and its response.; Write two-letter present tense action words on the board.; Lead learners to read the words.; Let learners read the action words as a group.; Let learners read the action words one after the other.; Demonstrate the action words with the class.; Let learners write two-letter present tense action words.', 590),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/Usage', 'Integrating Grammar in Written Language (Use of Action Words)', 'B2.5.3.1', 'Show an understanding of writing action words', 'B2.5.3.1.2', 'Write three-letter present tense action words', 'Write three-letter present tense action words on the board.; Lead learners to read the words.; Let learners read the action words as a group.; Let learners read the action words one after the other.; Demonstrate the action words with the class.; Let learners write three-letter present tense action words. B2.1.1.3 Use present tense action words in a simple sentence correctly.; Revise the action words introduced with learners.; Write simple sentences made up of present tense action words on the board.; Lead learners to read the sentences.; Let learners read the sentences as a group.; Let learners read the sentences one after the other.; Help learners to use present tense action words to form simple s entences.', 600),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/Usage', 'Integrating Grammar in Written Language (Use of Qualifying Words)', 'B2.5.4.1', 'Demonstrate knowledge on recognition and use of qualifying words (adjectives)', 'B2.5.4.1.1', 'Recognise comparative words/adjectives in sentences', 'Write sentences with adjectives underlined on flashcards.; Lead learners to read the sentences.; Let learners read the sentences on their own and correct them where necessary.; Use the flashcards to assist learners to recognise comparative words/adjectives in sentences.', 610),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/Usage', 'Integrating Grammar in Written Language (Use of Qualifying Words)', 'B2.5.4.1', 'Demonstrate knowledge on recognition and use of qualifying words (adjectives)', 'B2.5.4.1.2', 'Use comparative words/adjectives to form short sentence', 'Let learners sing a popular song.; Write sentences that show comparison and underline the word that show this on flashcards.; Lead learners to read the sentences.; Let learners read the sentences on their own and correct them where necessary.; Help learners to use adjectives to form comparative words in sentences.', 620),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/Usage', 'Integrating Grammar in Written Language (Use of Postpositions)', 'B2.5.5.1', 'Exhibit knowledge of understanding, recognising and using postpositions', 'B2.5.5.1.1', 'Write and use some postpositions in sentences', 'Let learners mention some traditional occupations they know.; Lead learners to sing songs associated with the traditional occupation.; Write sentences with postposition words underlined on flashcards.; Call learners individually to pick a card, show it to the class and read the sentence aloud to the class.; Use the flashcards to help learners to recognise the postpositions in the sentences and write the postpositions.; Let learners use postpositions to form simple sentences.', 630),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/Usage', 'Integrating Grammar in Written Language (Use of Simple and Compound Sentences)', 'B2.5.6.1', 'Exhibit knowledge of recognising simple sentence in writing', 'B2.5.6.1.1', 'Know the structure of a simple sentence', 'Let learners mention names of places and people they know.; Write simple sentences on flashcards.; Let learners read the sentences on the flashcard.; Discuss the various parts of the sentence with learners.; Show learners the structure of simple sentences on a card.; Lead learners through discussions to recognise the structure of a simple sentence.', 640),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/Usage', 'Integrating Grammar in Written Language (Use of Simple and Compound Sentences)', 'B2.5.6.1', 'Exhibit knowledge of recognising simple sentence in writing', 'B2.5.6.1.2', 'Recognise nouns in simple sentences', 'Let learners mention names of people and places they know.; Write simple sentences on flashcards and lead learners to read the sentences.; Let learners read the sentences as a group.; Call learners to read the sentences individually.; Assist learners to recognise nouns in simple sentences. B2.1.1.3 Use nouns to form simple sentences.; Revise the lesson on nouns with learners.; Write simple sentences on flashcards and call learners to read the sentences.; Let learners recognise the nouns in the sentence.; Let learners use the nouns to form simple sentences.', 650),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/Usage', 'Integrating Grammar in Written Language (Spelling)', 'B2.5.7.1', 'Exhibit knowledge of recognising and spelling simple words correctly', 'B2.5.7.1.1', 'Fill in blank spaces in simple words', 'Let learners say the letters of the alphabet.; Write words on a flashcard.; Let learners pick the flashcards in turns and let them mention the word on the card.; Lead learners to spell the words as a group and on individual bases.; Write the words on the board leaving out some letters.; Call learners to fill the blank spaces with the correct letter.; Write more words on the board leaving some letters out and call learners to fill the blank spaces with the missing letter.; Guide learners to fill in blank spaces in simple words.', 660),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/Usage', 'Integrating Grammar in Written Language (Spelling)', 'B2.5.7.1', 'Exhibit knowledge of recognising and spelling simple words correctly', 'B2.5.7.1.2', 'Write four-letter words correctly', 'Let learners say the letters of the alphabet as a group.; Call individual learners to say the letters of the alphabet.; Write four-letter words on the board.; Lead learners to say the words aloud.; Let learners say the words on their own.; H elp learners to write four-letter words correctly.', 670),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Extensive Reading/Children’s Literature/Library', 'Building the Love and Culture of Reading', 'B2.6.1.1', 'Demonstrate knowledge by reading short and simple sentences made up of words they have learnt to speak', 'B2.6.1.1.1', 'Read short passages of simple sentences of about four to five words', 'Let learners sing a traditional occupational song they know.; Provide learners with reading books (the book should have a short passage according to the number of words prescribed).; Lead learners to read the passage in the book.; Let learners read the passage in turns.; Assist learners to read short passages of simple sentences of about four to five words in other parts of the book.', 680),
('Basic 2', 'Ghanaian Language', 'ghanaian language', 'Extensive Reading/Children’s Literature/Library', 'Read Aloud With Children', 'B2.6.2.1', 'Demonstrate knowledge by reading short and simple sentences made up of words they have learnt', 'B2.6.2.1.1', 'Read short passages of simple sentences of about five to six words', 'Let learners sing a traditional occupational song they know.; Provide learners with reading books (the book should have a short passage according to the number of words prescribed).; Lead learners to read the passage in the book.; Let learners read the passage in turns.; Assist learners to read short passages of simple sentences of about five to six words in other parts of the book.', 690),
('Basic 2', 'History', 'history', 'My Country Ghana', 'The People Of Ghana', 'B2.2.1.1', 'Show understanding of the characteristics of some of the ethnic groups in Ghana', 'B2.2.1.1.1', 'State the characteristics of the ethnic groups in Ghana Enquiry route: What are the characteristics of the ethnic groups? What differentiates one ethnic group from the other?', '1. Identify the administrative regions of Ghana; 2. Locate the ethnic groups in each region on a map of Ghana; 3. With the aid of a slide/video/TV/internet, identify the regions and ethnic groups in Ghana; 4. Match the ethnic groups with their region; 5. List the administrative regions in the order in which they created (starting with the oldest region)', 10),
('Basic 2', 'History', 'history', 'My Country Ghana', 'Major Historical Locations', 'B2.2.4.1', 'Exhibit knowledge of the history of the major historical locations in Ghana', 'B2.2.4.1.1', 'Discuss the history of Ghana’s major historical locations. Examples include Kumasi military museum, Komfo Anokye Sword, Assin Manso slave site, Gbewa Palace. Enquiry route: Where are the major historical locations? What do these locations tell us about our history?', '1. Identify the major historical locations in Ghana (starting with the oldest location).; 2. Show and discuss video/documentary/stories/slides about the history of these major historical locations in Ghana.; 3. Retell the history of these major historical locations in Ghana.; 4. Interact with knowledgeable persons/ opinion leaders/ chiefs/ resource persons to tell the history of any historical location in your community or district.; 5. Visit any historical site in their community.; 6. Retell the history of major sites in their community.', 20),
('Basic 2', 'History', 'history', 'My Country Ghana', 'Some Selected Individuals', 'B2.2.5.1', 'Exhibit knowledge of the history of the major historical locations in Ghana', 'B2.2.5.1.1', 'Exhibit understanding of Ghanaian women who have contributed significantly to Ghana’s development', null, 30),
('Basic 2', 'History', 'history', 'Europeans in Ghana', 'International Trade Including Slave Trade', 'B2.3.2.1', 'Understand that trade was the major reason why the Europeans settled in Ghana', 'B2.3.2.1.1', 'Describe how early trade was carried out between Ghanaians and Europeans Enquiry route: How was trade with the Europeans first carried out? How did the method of trade change with time? What items were traded? What towns emerged out of the trade between Ghanaians and Europeans?', '1. Describe how early trade was carried out between Ghanaians and the Europeans; 2. Organise learning corners with real items or pictures of items brought by the Europeans such as Gin, Gun, Gun Powder, Textiles, Tobacco, Iron Bars, Elephant tusks, Ivory, Gold.; 3. Role play the barter trade in those items.; 4. Use internet to identify countries with the items they brought that remained part of everyday Ghanaian life. e.g. the Dutch and wax prints.; 5. Name the towns that emerged on the coast as a result of European trade with Ghanaians.', 40),
('Basic 2', 'Mathematics', 'maths', 'Number', 'Counting, Representation, Cardinality & Ordinality', 'B2.1.1.1', 'Count and estimate quantities from 0 to 1000', 'B2.1.1.1.1', 'Use number names, counting sequences and how to count to find out “how many?”', 'E.g.; 1. Skip count forwards and backwards to and from 1000 respectively by 2s, 5s and 10s, starting at 0 or at multiples of 2, 5, 10, 50 and 100; Identify and correct errors or omissions in counting or skip counting sequences E.g.; 2. Count by 2s, 5s or 10s, to answer “how many?” questions about as many as 100 or 1000 objects E.g.3. Represent the number of objects in a group with a written numeral to 1000 E.g.; 4. Estimate the number of objects in a group of up to 1000 describe the estimation strategy used; Select an appropriate estimate among all those given and justify the choice', 10),
('Basic 2', 'Mathematics', 'maths', 'Number', 'Counting, Representation, Cardinality & Ordinality', 'B2.1.1.1', 'Count and estimate quantities from 0 to 1000', 'B2.1.1.1.2', 'Identify numbers in different positions around a given number in a number chart. (1-1000)', 'E.g.; 1. Display a number chart with numbers between 0 and 100 and have learners identify numbers in different positions around a given number. Put learners in convenient groups and give each group a number grid and have them identify numbers in different positions around a chosen number. For example, choose 18 and identify numbers above, below, to the right or to the left etc. 24 48 75 12 16 18 86 40 115 259 134 529 203 325 719 686 685 915 982 827', 20),
('Basic 2', 'Mathematics', 'maths', 'Number', 'Counting, Representation, Cardinality & Ordinality', 'B2.1.1.1', 'Count and estimate quantities from 0 to 1000', 'B2.1.1.1.3', 'Use number names and non-standard units (marked 10s and 1s) for measuring (lengths and volumes) to count to find out “how long or how much?” up to 999', 'E.g.; 1. Have learners use their feet, strides, arms, hand-span and referent materials such as sticks or threads to find how long a table, window and door frames etc., by counting the number of times their feet, hand-span and referent materials is able to do this E.g.; 2. Have learners use empty container such as bottles, cups etc. to determine the capacity of other bigger containers by counting to find how much (the number of times) the bottles, cups etc. is able to do this', 30),
('Basic 2', 'Mathematics', 'maths', 'Number', 'Counting, Representation, Cardinality & Ordinality', 'B2.1.1.1', 'Count and estimate quantities from 0 to 1000', 'B2.1.1.1.4', 'Demonstrate a conceptual understanding of place value of whole numbers between 0 and 100', 'E.g.; 1. Develop a conceptual understanding of place value of whole numbers between 0 and 1000 by: - explain and show- with bundles of 10s and 1s and a tens frame - the meaning of each digit in a 2-digit number (when the two Tens Frame digits are different, as well as Hundred Tens Ones when the two digits are the same) and representing the number in a tens frame (Use other possible representations of place value which include manipulatives such as threaded 100s, 10s, and loose bottle caps; and multi-base ten material (units, flats and squares) with numeral cards - decompose or partition numbers to 1000 into hundreds, tens and ones (e.g.: 153 = 100 + 50 + 3, or 153 = 100 +; 53) - explain why the value of a digit depends upon its placement within a numeral. - read a number by indicating the value of each digit (i.e., reading 43 as forty-three and not four three. E.g.; 2. Partition or decompose numbers to 100 and then to 1000 into equivalent expressions (e.g.: 47 = 20 + 20 + 7, or 30 + 10 + 7, etc.); Tens', 40),
('Basic 2', 'Mathematics', 'maths', 'Number', 'Counting, Representation, Cardinality & Ordinality', 'B2.1.1.1', 'Count and estimate quantities from 0 to 1000', 'B2.1.1.1.5', 'Represent number quantities up to 1000 in equivalent ways focusing on place value and equality', 'E.g.; 1. Demonstrate an understanding of how place value determines the relative size of numbers up to 1000 by: describing the relative size of two or more numbers (i.e., saying whether one number is a little or a lot bigger or smaller than another and justifying the answer) E.g.2 Represent and describe numbers to 1000 in equivalent ways (e.g., 147 is 3 less than 150, is 7 more than 140, is almost half of 300, is a little larger than 145 but a lot larger than 15, etc.) E.g.; 3. Arrange groups of up to 100 objects in equal groups in more than 1 way and describe the arrangement; or describe the arrangement and how many are left over (e.g. arrange 66 as two groups of 33 or six groups of 11, or 3 groups of 22 or 5 groups of 12 and 6 left over)', 50),
('Basic 2', 'Mathematics', 'maths', 'Number', 'Counting, Representation, Cardinality & Ordinality', 'B2.1.1.1', 'Count and estimate quantities from 0 to 1000', 'B2.1.1.1.6', 'Use place value to compare and order whole numbers up to 100 using comparative language, numbers, and symbols (>, <, or =)', 'E.g.; 1. Identify which of two given numbers is bigger (or smaller), explain why, and represent the relationship using the symbols< and > E.g.; 3. Put a small group of numbers in increasing or decreasing order and justify the order using place value E.g.; 4. Identify the missing numbers in a section of number line from 1 to 100 or in a hundreds chart and justifying the answer using place value E.g.; 5. Solve word problems that involve comparing quantities up to 100 (i.e., Ahmed has 23 chickens. Amina has; 46. What can you say?)', 60),
('Basic 2', 'Mathematics', 'maths', 'Number', 'Counting, Representation, Cardinality & Ordinality', 'B2.1.2.1', 'Demonstrate conceptual understanding of operations of addition and subtraction with sums up to 100', 'B2.1.2.1.1', 'Use conceptual understanding of addition and subtraction to add, and subtract numbers to 100', 'E.g.; 1. Add a given set of numbers in two different ways (e.g. 35 + 54 and 54 + 35 or 18 + 12 + 3 and 3 + 18 +; 12) and explaining why the order in which numbers are added does not change the sum E.g.; 2. Explain why the difference or sum is the same as the initial number when 0 is added or subtracted from a number (e.g., why 27 + 0 = 27 or 55 – 0 =; 55) E.g.; 3. Match a word problem to a missing addend (e.g.,3 4 + ___ = 57), missing subtrahend1 (e.g. 27 - __ =; 24) or missing minuend (__ - 54 =; 63) statement E.g.; 4. Create an addition or subtraction number sentence and word problem for a number up to 100 (i.e., given the solution 53, create an addition or subtraction sentence with an answer of 53 and a corresponding word problem).', 70),
('Basic 2', 'Mathematics', 'maths', 'Number', 'Counting, Representation, Cardinality & Ordinality', 'B2.1.2.2', 'Demonstrate an understanding of the concept of “not equal to” to solve addition and subtraction problems with sums up to 100', 'B2.1.2.2.1', 'Use the concept of "equal to" and "not equal to" to solve addition and subtraction problems with sums up 100', 'E.g.; 1. Explaining that that'' “≠” means “not the same as” or “not equal to” - Constructing and drawing two sets that are not equal, explaining why they are not equal and recording the relationship using the symbol ≠ (e.g., ≠ ); Changing two given sets, equal in size, to create sets that are not equal (e.g., change = to ≠ ), explain the changes made and why; - Determining whether two sides of a given number sentence are equal or not and using the appropriate symbol to represent the relationship (e.g., 16 ≠ 8 + 5) E.g. 2. Using a symbol () to represent an unknown in addition/subtraction statements to 100. E.g. 3. Demonstrate an understanding of the relationship between addition and subtraction by describing a subtraction as an equivalent addition and vice versa; i.e. finding the missing addend. (For example, that subtract 40 – 28 is the same as finding the number that must be added to 28 to make 40). 40 − 28 = What? Means 28 + What? = 40 Or if given 40 - 28 = ___ change question to 28 +__ = 40. The answer is 12, so 40 - 28 = 12).', 80),
('Basic 2', 'Mathematics', 'maths', 'Number', 'Counting, Representation, Cardinality & Ordinality', 'B2.1.2.3', 'Develop and use strategies for mentally computing basic additions and subtraction facts to 19', 'B2.1.2.3.1', 'Use mental strategies for basic addition facts to 19 and related subtraction facts to 19', 'E.g.; 1. Demonstrate fluency with addition and subtraction-related relationships by:; Quickly naming numbers that are 1, 2, or 10 more or less than a number between 1 and 100, or 5 more than a number that is a multiple of 5; Quickly Identifying the double of a number between 1 and 12; Add and subtract combinations to 10 quickly and accurately. -', 90),
('Basic 2', 'Mathematics', 'maths', 'Number', 'Counting, Representation, Cardinality & Ordinality', 'B2.1.2.4', 'Develop and use conventional and personal strategies for computing additions up to 100', 'B2.1.2.4.1', 'Use conventional strategy to add and subtract within 100', 'E.g.; 1. Use objects (groups of tens and ones) or drawings to model addition and subtraction of 1 and 2 digit numbers (with answers within 100), with and without regrouping) and record the process symbolically, using an addition or subtraction frame. Addition Frame Subtraction Frame Tens Ones Tens Ones + -', 100),
('Basic 2', 'Mathematics', 'maths', 'Number', 'Counting, Representation, Cardinality & Ordinality', 'B2.1.2.4', 'Develop and use conventional and personal strategies for computing additions up to 100', 'B2.1.2.4.2', 'Use personal strategies to add and subtract within 100', 'E.g.; 1. Decompose a number into easier numbers to add and doing partial sums- Decomposing one number into easier numbers to add E.g., when adding 28 + 47, record think 20 + 40 + 8 + 7, which is the same as 60 + 15 which is the same as 75', 110),
('Basic 2', 'Mathematics', 'maths', 'Number', 'Counting, Representation, Cardinality & Ordinality', 'B2.1.2.4', 'Develop and use conventional and personal strategies for computing additions up to 100', 'B2.1.2.4.3', 'Solve one-step and multi-step word problems involving addition and subtraction within 100 using a variety of strategies based on place value, including algorithms', 'E.g.; 1. Yaw has 32 books. Aisha added 13 more books to Yaw’s books. How many books do they have altogether? E.g.; 2. Mr. Haruna gave 45 books to Yaa’ She gave 11 of the books to her sister. How many books are left? E.g.; 3. Araba needs 8 Ghana cedis to buy exercise books. She has only 5 Ghana cedis. How much money does she need in order to buy the books?', 120),
('Basic 2', 'Mathematics', 'maths', 'Number', 'Fractions', 'B2.1.3.1', 'Develop an understanding of halves and fourths using concrete and pictorial representations [Exclude notation here]', 'B2.1.3.1.1', 'Understand the fraction one-half and one-quarter as the quantity obtained by taking 1 part when a whole is partitioned into two or four equal parts', 'E.g.; 1. Use concrete objects to explain the fraction one-fourth as the quantity obtained by taking 1 part when a whole object is partitioned into four equal parts. E.g.; 2. Use pictorial representations to explain the fraction one- fourth as the quantity obtained by taking 1 part when a whole object is partitioned into four equal parts. E.g.; 3. Use pictorial representations to help learners sort fractions into those that are halves and those that are one-fourths.', 130),
('Basic 2', 'Mathematics', 'maths', 'Number', 'Fractions', 'B2.1.3.1', 'Develop an understanding of halves and fourths using concrete and pictorial representations [Exclude notation here]', 'B2.1.3.1.2', 'Count in halves and quarters (fourths) using concrete and pictorial representations) of halves and fourths', 'E.g.; 1. Show several fourths of concrete objects (or card cut outs) and have them count them in fourths (using the language one-fourth, two- fourths, three-fourths, etc.) E.g.; 2. Show learners several pictorial representations of fourths and have them count (using the language one-fourth, two-fourths, three-fourths, etc.)', 140),
('Basic 2', 'Mathematics', 'maths', 'Number', 'Fractions', 'B2.1.3.1', 'Develop an understanding of halves and fourths using concrete and pictorial representations [Exclude notation here]', 'B2.1.3.1.3', 'Determine the number of halves and quarters in a whole', 'E.g.; 1. Show learners several pictorial representations (or card cut outs) of halves, fourths and wholes and ask them to state the relationship between (i) a whole and one-half; (ii) a whole and one-fourth, and (iii) one- half and one-fourth.', 150),
('Basic 2', 'Mathematics', 'maths', 'Number', 'Money', 'B2.1.4.1', 'Determine the value of coins and notes in order to solve monetary transactions', 'B2.1.4.1.1', 'Recognise Ghanaian coins, and currency notes to include at least 1 cedi, 2 cedis, 5 cedis, 10 cedis, 20 cedis and 50 cedis and determine the value of a collection of coins and notes up to at least 50 Ghana cedis', 'E.g.; 1. Display the Ghanaian cedi (coins and notes) currently being used for transaction in Ghana and initiate discussion on the need for monetary transaction. Learners touch feel and say the features of each coin E.g.; 2. Introduce the notes (i.e. 1 cedi, 2 cedis, 5 cedis 10 cedis etc.) in turns and have learners examine and talk about its features E.g.; 3. State the relationship between ¢2 and ¢10; ¢5 and ¢10; ¢2 and ¢20; ¢5 and ¢20, ¢10 and ¢50', 160),
('Basic 2', 'Mathematics', 'maths', 'Algebra', 'Patterns and Relationships', 'B2.2.1.1', 'Recognize, create, extend, describe, and use patterns and rules to solve mathematical tasks', 'B2.2.1.1.1', 'Demonstrate an understanding of increasing and decreasing number patterns E.g.1. Identify the pattern rule used to create a pattern that increases or decreases by 2, 5 or 10. (i.e. in the pattern 2, 4, 6, 8 ,… - the rule is “add 2 or jump by 2) and extend the pattern for the next 2 or 3 terms', 'E.g.; 2. Identify errors or omissions in increasing or decreasing patterns (e.g. 5, 10, 20, 25, 30…) and explain the reasoning and strategy used to identify the pattern.', 170),
('Basic 2', 'Mathematics', 'maths', 'Algebra', 'Patterns and Relationships', 'B2.2.1.1', 'Recognize, create, extend, describe, and use patterns and rules to solve mathematical tasks', 'B2.2.1.1.2', 'Identify, create and describe the rule for simple number patterns involving repeated addition or subtraction, skip counting and arrays of objects', 'E.g.; 1. Find the missing terms in the following: - 9, 1, 3, 5, 9, 1, 3, 5, ___ ; ___ - 2, 4, 6, 8, 10, ___ ; ___, - 5, 10, 15, 20___ , ___ ; or - 54, 55, 56, 57, ___ , ___ . E.g.; 2. Identify and describe the rules for the following patterns - 2, 4, 6, 8, 10, … (the rule is “add two”) - 5, 10, 15, 20, … - 20, 18, 16, 14, …', 180),
('Basic 2', 'Mathematics', 'maths', 'Geometry and Measurement', 'D and 3D Shapes', 'B2.3.1.1', 'Describe and analyse 2D shapes and 3D objects', 'B2.3.1.1.1', 'Identify the common features or attributes of a collection of 3D objects (spheres, cylinders, cones, pyramids, cubes) of different dimensions or orientations', 'E.g.; 1. Recognise and name 3D objects having specific features or attributes (number of equal faces, types of faces, number of corners, etc.) E.g.; 2. Sort a collection of 3D objects by 1 or 2 features and explain the sorting rule use E.g.; 3. Identify examples of these 3D objects in the classroom and community', 190),
('Basic 2', 'Mathematics', 'maths', 'Geometry and Measurement', 'D and 3D Shapes', 'B2.3.1.1', 'Describe and analyse 2D shapes and 3D objects', 'B2.3.1.1.2', 'Identify the common features or attributes of a collection of 2D shapes (squares, triangles, rectangles, circles, pentagons, hexagons) of different dimensions or orientations', 'E.g.; 1. Recognize, draw and name 2D shapes having specific features or attributes (for example a given number of angles or edges/sides E.g.; 2. Sort a collection of 2D shapes by 1 or 2 features or attributes and explain the sorting rule used E.g.3. Identify examples of these 2D shapes in the classroom and community. For example, take learners on a tour around the classroom and the school compound. Point out items to them and encourage them to name the 2D shape in the items', 200),
('Basic 2', 'Mathematics', 'maths', 'Geometry and Measurement', 'D and 3D Shapes', 'B2.3.1.1', 'Describe and analyse 2D shapes and 3D objects', 'B2.3.1.1.3', 'Create two-dimensional shapes based on given attributes, including number of sides and vertices', 'E.g.; 1. Identify the 2D faces of a given 3D object E.g.; 2. Identify 3D objects in the environment that have parts similar to a given 2D shape (find the parts of a can or bucket that are similar to a circle) E.g.; 3. learners identify the number of sides, faces and vertices of 2D plane figures E.g. 4 learners draw 2D shapes with given sides or vertices', 210),
('Basic 2', 'Mathematics', 'maths', 'Geometry and Measurement', 'Position/Transformation', 'B2.3.2.1', 'Demonstrate that the length of an object does not change with its placement or direction', 'B2.3.2.1.1', 'Prove that the placement or direction of a shape or object does not change its length', 'E.g.; 1. Put sticks of equal length in different places and directions and ask learners to identify the longest; viz. which stick in the figure is longest? Then ask them to pick the sticks and put them side by side to see if they have equal length.', 220),
('Basic 2', 'Mathematics', 'maths', 'Geometry and Measurement', 'Measurement- Length, Capacity, Mass and Time', 'B2.3.3.1', 'Use non-standard units for measuring lengths, heights, mass and distance around objects', 'B2.3.3.1.1', 'Demonstrate an understanding of how to measure lengths, capacities or mass - directly or indirectly - using non-standard units', 'E.g.; 1. Identifying which of two non-standard units would be a better choice for measuring the length, capacity or mass of an object. (E.g. Put a table (see example) of lengths to be measured and object to be used to measure (thumb width, paper clips, pencil lengths, etc.), estimates, and actual measures. Have learners copy table in their exercise book, record their personal estimates and then work with a partner to measure and record the actual measurements. As learners work, go around the classroom to ensure they are using appropriate procedures for; Math textbook; Math textbook; Desk; Desk; measuring) E.g. 2. Explain why the number of non-standard units an object measures varies depending upon the size of the non-standard unit used (example: why the measuring lengths using paperclips results in a higher number than measuring lengths with pencils).', 230),
('Basic 2', 'Mathematics', 'maths', 'Geometry and Measurement', 'Measurement- Length, Capacity, Mass and Time', 'B2.3.3.1', 'Use non-standard units for measuring lengths, heights, mass and distance around objects', 'B2.3.3.1.2', 'Develop an understanding of measuring as a process of comparing three or more items', 'E.g.; 1. Learners bring together several collection of objects in their environment and compare (directly and indirectly) using words such as smaller, smallest, longer, longest, bigger, biggest, heavier, heaviest etc.', 240),
('Basic 2', 'Mathematics', 'maths', 'Geometry and Measurement', 'Measurement- Length, Capacity, Mass and Time', 'B2.3.3.2', 'Use standard units to measure lengths, heights, mass and distance around objects. cont’d', 'B2.3.3.2.1', 'Recognize the need for standard unit of measurement of length', 'E.g.; 1. Mark a learner’s height on the wall and ask 4 learners to use their hands pan to measure the height. On the basis of the different measures that would be obtained, get learners to establish the need for use of standard units E.g.; 2. Estimate the measure in non-standard units, and then comparing the estimate with the actual measure. E.g. Bring two learners of different heights to the front of the class, take the height of one pupil. On the basis of that height ask a pupil to estimate the height of the other pupil and then measure the actual height to compare with their estimation', 250),
('Basic 2', 'Mathematics', 'maths', 'Geometry and Measurement', 'Measurement- Length, Capacity, Mass and Time', 'B2.3.3.3', 'Develop an understanding of the measurement of time taken by events using arbitrary units and the hour', 'B2.3.3.3.1', 'Read the calendar and solve problems involving the number of days in a week and number of months in a year', 'E.g.; 1. Using the calendar to do the following: - Identify or read the day of the week and the month of the year for a given calendar date. - Identify the day (or month) that comes before or after a given day (or month) - Name, order and count the days in a week and the months in a year, E.g.; 2. Ask learners to say the rhyme “Thirty-days has September” 30 days has September, April, June, and November. All the rest have 31, Except for February alone, which has 28 days clear, and 29 in each leap year.', 260),
('Basic 2', 'Mathematics', 'maths', 'Geometry and Measurement', 'Measurement- Length, Capacity, Mass and Time', 'B2.3.3.3', 'Develop an understanding of the measurement of time taken by events using arbitrary units and the hour', 'B2.3.3.3.2', 'Use arbitrary units and hour on the clock to measure time to complete simple events', 'E.g.; 1. Ask learners to tell how much time (in terms of arbitrary unit timers like claps, water timers, etc.) it would take to - walk round the classroom - to sing a song - to eat one banana E.g.; 2. Ask learners to tell describe events that take an hour or more or less than an hour. E.g.; 3. Ask learners to watch the clock each hour and note how long they stay in school each day.; 30 days has September, April, June, and; November. All the rest have 31,; Except for February alone, which has 28 days; clear, and 29 in each leap year.', 270),
('Basic 2', 'Mathematics', 'maths', 'Data', 'Data Collection, Organisation, Presentation, Interpretation and Analysis', 'B2.4.1.1', 'Collect and record data about self and others and use it to answer and pose questions', 'B2.4.1.1.1', 'Use tallies, checkmarks, charts, lists or objects to collect and organize data to answer and pose questions about themselves, others, or surroundings', 'E.g.; 1. “What is our favourite food or colour or sport?” E.g.; 2. Answer and/or pose questions, and justify the answers, based on the organized data', 280),
('Basic 2', 'Mathematics', 'maths', 'Data', 'Data Collection, Organisation, Presentation, Interpretation and Analysis', 'B2.4.1.2', 'Construct and interpret concrete graphs and pictographs', 'B2.4.1.2.1', 'Draw and interpret concrete graphs and pictographs', 'E.g. 1 Use one-to-many correspondence to create concrete graphs or pictographs to represent data collected (up to 3 categories of data) E.g.; 2. Using a one-to-one correspondence solve simple problems (how many altogether, comparing, or take apart problems) on concrete graphs or pictographs.', 290),
('Basic 2', 'Religious & Moral Education', 'rme', 'God, His Creation and Attributes', 'God the Creator', 'B2.1.1.1', 'Demonstrate an appreciation of God’s creation', 'B2.1.1.1.1', 'Mention attributes of God that reveal His nature as Sustainer of life', 'In groups, lead learners to discuss the attributes of God as the Sustainer of life: - Giver of rain and sunshine, - the One who makes plants grow, - the Giver of air, etc.; Let learners mention other attributes of God in their local languages.; Let learners explain the attributes of God relevant to their daily life, e.g. God gives life, rain and air.', 10),
('Basic 2', 'Religious & Moral Education', 'rme', 'God, His Creation and Attributes', 'The Environment', 'B2.1.2.1', 'Appreciate the environment as God’s creation', 'B2.1.2.1.1', 'Explain the importance of the environment', 'Take a nature walk of the school environment with learners to observe: - things of natural existence (objects God created): trees, stones, animals, etc., - things created by humankind: buildings, cars, tables, chairs, etc.; In groups, let learners examine things made by humankind and identify the materials used in making the things. - Guide learners to talk about the importance of the environment. (survival of God’s creation depends on the environment): air, food, water, shelter, etc.', 20),
('Basic 2', 'Religious & Moral Education', 'rme', 'God, His Creation and Attributes', 'The Environment', 'B2.1.2.1', 'Appreciate the environment as God’s creation', 'B2.1.2.1.2', 'Demonstrate human activities that destroy God’s creation or the environment', 'Guide learners to talk about activities that destroy the environment: indiscriminate cutting down of trees, illegal mining activities (galamsey), pollution of water bodies, etc.; Let learners know that all these activities lead to climate change – heat, floods, rainstorms, less rainfall pattern, drought, famine, etc.; Group learners to record data on human activities that destroy the environment and present to class for discussion. NB Nature walk, video clips and pictures on environmental degradation can be used.; Let learners draw and colour various aspects of the environment: - safe environment, - unsafe environment, etc.; Let learners talk about the desired environment.', 30),
('Basic 2', 'Religious & Moral Education', 'rme', 'God, His Creation and Attributes', 'Purpose of God’s Creation', 'B2.1.3.1', 'Appreciate things created by God', 'B2.1.3.1.1', 'Explain the purpose of God’s creation', 'Group learners to discuss the usefulness of plants and animals to humankind.; Let learners identify the uses of animals and plants.; Let learners draw and colour useful plants and animals.', 40),
('Basic 2', 'Religious & Moral Education', 'rme', 'God, His Creation and Attributes', 'Religious Worship in the Three Major Religions in Ghana', 'B2.2.1.1', 'Explain the importance of religious worship', 'B2.2.1.1.1', 'Explain the importance of worship', 'Engage learners with video clips or pictures of people at worship.; If possible, take learners to the church, mosque or the shrine to observe the mode of worship.; Lead learners to talk about the importance of worship at home, church or mosque and in school: - It is a command from God to serve Him.', 50),
('Basic 2', 'Religious & Moral Education', 'rme', 'God, His Creation and Attributes', 'Religious Worship in the Three Major Religions in Ghana', 'B2.2.1.1', 'Explain the importance of religious worship', 'B2.2.1.1.2', 'Sing and recite simple texts from the three main religions in Ghana', 'Lead learners to mention popular religious songs and recitations in the three main religions in Ghana.; Let learners sing or recite some simple verses from the Bible or Quran and some sayings from the oral tradition. - The Lord’s Prayer (Christian) - Al-Fãtihah (Islam) - Traditional prayer (ATR); Let learners write simple texts from the religious songs and recitations.', 60),
('Basic 2', 'Religious & Moral Education', 'rme', 'God, His Creation and Attributes', 'Festivals in the Three Major Religions', 'B2.2.2.1', 'Explain the importance of religious festivals', 'B2.2.2.1.1', 'Demonstrate activities which take place during the celebration of festivals', 'Let learners mention religious festivals they have witnessed or head of. Islam - Eid-ul-Fitr, Eid-ul-Adha, etc., Christianity- Easter, Christmas, etc., Traditional - Kundum, Odwira, Damba, Bugum, Yam Festival, etc.; Let learners, in groups, describe how various festivals are celebrated.; Let learners role-play or dramatise activities that take place during the festivals: merry- making, sharing, family re-union, worship, etc.; Let learners draw scenes from festivals.', 70),
('Basic 2', 'Religious & Moral Education', 'rme', 'Religious Leaders', 'Early Life of the Leaders of the three Major Religions', 'B2.3.1.1', 'Explain the importance of religious festivals', 'B2.3.1.1.1', 'Narrate the story of the early life of the religious leaders in the three religions in Ghana', 'Let learners mention the names of the religious leaders: Jesus Christ, the Holy Prophet (Sallahu Alaihi Wasallam-S.A.W (Peace be upon Him)) Okomfo Anokye, Toha Zie, Egya Ahor, etc.; Discuss with learners the early lives of these religious leaders. - The Lord Jesus Christ; - The Holy Prophet Muhammad (SAW), - A traditional leader.; In groups, let learners role-play some important aspects of the early life of a religious leader.', 80),
('Basic 2', 'Religious & Moral Education', 'rme', 'Religious Leaders', 'Early Life of the Leaders of the three Major Religions', 'B2.3.1.1', 'Explain the importance of religious festivals', 'B2.3.1.1.2', 'Outline the moral lessons in the early lives of the religious leaders', 'Lead learners to talk about the moral lessons they have learnt from the discussions about the religious leaders of the three main religions in Ghana.; Guide learners to explain how they will apply the moral lessons learnt from the religious leaders in their daily lives.; Let learners dramatise the moral lives of the religious leaders.', 90),
('Basic 2', 'Religious & Moral Education', 'rme', 'The Family and the Community', 'Roles and Relationships', 'B2.4.1.1', 'Describe the roles of the family and community in their daily lives', 'B2.4.1.1.1', 'Identify things that families do to show their commitment to God', 'Let learners mention the religious activities their families perform: morning devotion, going to church, mosque or the shrine.; Let learners in groups, identify the number of times religious activities are performed during the day, week and occasionally.; Let learners to role-play what their families do to show commitment to God e.g. worship, offertory, Sadaqah, Zakat, prayer and fasting, etc.', 100),
('Basic 2', 'Religious & Moral Education', 'rme', 'The Family and the Community', 'Roles and Relationships', 'B2.4.1.1', 'Describe the roles of the family and community in their daily lives', 'B2.4.1.1.2', 'Explain the need for commitment to God', 'Guide learners to explain the meaning of commitment.; Let learners discuss why we need to be committed to God: - It is a command from God. - It attracts blessings from God.; Let learners talk about things they do to show their commitment to God.; Let learners, in pairs, share their personal experiences about things they do at home, school, church or mosque and community to show their commitment to God.; Through questions and answers, let learners share their personal experiences in class.', 110),
('Basic 2', 'Religious & Moral Education', 'rme', 'The Family and the Community', 'Roles and Relationships', 'B2.4.1.1', 'Describe the roles of the family and community in their daily lives', 'B2.4.1.1.3', 'Describe factors that promote good relationships between children and their parents', 'Lead learners to talk about good relationships.; Let learners talk about things that promote good relationships: comportment, respect, love, obedience, humility, friendliness, etc.; Let learners identify their friends and say things they like about them.; Let learners dramatise behaviours that show good relationships.', 120),
('Basic 2', 'Religious & Moral Education', 'rme', 'The Family and the Community', 'Personal Safety in the Community', 'B2.4.2.1', 'Describe the roles of the family and community in their daily lives', 'B2.4.2.1.1', 'Describe ways of promoting personal hygiene and safety in the community. Personal Hygiene', 'Have learners mention things they need in promoting personal hygiene practices: water, soap, tooth brush and tooth paste, nail cutter, etc.; Let learners talk about things they do to show personal hygiene practices: bathing twice a day, brushing of the teeth, at least, twice daily, washing of clothes regularly, washing of hands regularly, etc.; Through dramatisation, let learners demonstrate personal hygiene practices.; Let learners draw items used in keeping their bodies clean. Safety in the Community; Have learners mention things they need in promoting safety in the community: brooms, scrubbing brushes, rakes, cutlasses, street lights, etc.; Let learners talk about things that must be done to ensure safety in the community: clearing of surroundings, de-silting choked gutters, creating watch-dog groups and reporting crimes or criminals (bad people or bad behaviours), etc.; Help learners demonstrate safe community practices.; Let learners draw items used in keeping our communities clean.; Let learners draw people who keep our communities safe.', 130),
('Basic 2', 'Science', 'science', 'Diversity of Matter', 'Living and Non-living Things', 'B2.1.1.1', 'Demonstrate understanding of the physical features and life processes of living things and use this understanding to classify them', 'B2.1.1.1.1', 'Know the basic structure of plants (roots, stem, leaves, flowers)', 'Observe pictures or watch a video on different plants; Working in groups, learners uproot young plants from school surroundings with the assistance of the teacher and bring them to class; Learners examine the plants in groups to identify the basic parts (roots, stem, leaves and flowers); Learners describe the basic physical features of plants (roots, stem and leaves and flowers); Teacher asks learners some questions:; 1) which part of the plant is hidden in the soil?; 2) Which part of the plant was seen above the soil?; Learners sing songs, rhymes and poems relating to the topic.; Teacher asks learners: what will happen if there are no plants in their community.; Learners draw and label a plant NB: Build a stock of young plants for the activity. Paste a picture of a large plant in the class', 10),
('Basic 2', 'Science', 'science', 'Diversity of Matter', 'Living and Non-living Things', 'B2.1.1.2', 'Understand the differences between living, non-living things and things which have never been alive', 'B2.1.1.2.1', 'Describe the basic structure of animals (head, limbs and trunk)', 'Learners watch videos or observe pictures of different animals; Learners name some animals from the pictures; Learners identify the basic parts of animals (head, limbs and trunk); Engage learners to draw animals of their choice Proj ect: Learners design and mould animals of their choice and identify the basic parts of those animals (head, limbs and trunk). Learners explain why they chose to mould those particular animals.', 20),
('Basic 2', 'Science', 'science', 'Diversity of Matter', 'Living and Non-living Things', 'B2.1.1.2', 'Understand the differences between living, non-living things and things which have never been alive', 'B2.1.1.2.2', 'Group things collected from the environment into living and non-living things', 'Learners bring pictures of various living and non-living things.; Go on a nature walk, observe and collect things from the environment.; In groups learners work to sort out things into living and non-living things (based on the pictures and items collected from the environment).; Learners give reasons for their groupings.; Draw and colour some of the things collected. Project: Learners create some living and non-living things from materials such as clay, blu tack, cardboard or paper.', 30),
('Basic 2', 'Science', 'science', 'Diversity of Matter', 'Materials', 'B2.1.2.1', 'Recognise materials as important resources for providing human needs', 'B2.1.2.1.1', 'Know the common properties of materials such as soft, hard, rough, smooth, opaque, transparent, bendable', 'Learners collect and bring a variety of everyday materials from the home, school and community. Materials should include items such as cotton wool, pieces of cloths, pieces of paper, cardboard, wood, plastics, polythene bags (coloured and transparent), soil samples, marbles (rough and smooth) chalk, crayon, pen, straws.; Learners sort and group the materials based on texture (hard or soft), and size (big or small).; Group materials into those that they can see through (transparent) and those that we cannot see through (opaque) with the teacher’s assistance; Provide materials that can bend, for learners to observe.; Learners feel and draw materials that are hard, soft, smooth, etc.; Learners display their drawings in class for discussion.; Know that the properties of a given material enable it to be used for making certain products, e.g. clay is used for making pots because it can be moulded without breaking. Raffia palm is used for making basketry because it can bend easily. Project: Learners use different materials to create new items such as paper fans, toy cars, toy planes, cooking pans, hats and earthen ware.', 40),
('Basic 2', 'Science', 'science', 'Diversity of Matter', 'Materials', 'B2.1.2.2', 'Know that substances can exist in different physical states (solid, liquid, gas): many substances can be changed from one state to another by heating or cooling', 'B2.1.2.2.1', 'Describe the properties of solids, liquids, and gases', 'Display different materials (real or pictures) in the solid, liquid or gaseous state, e.g. ice, water, vapour, fruit juice, oil and gravels.; Learners observe the materials and describe their properties in terms of appearance, shape, flow, and how easily they can be squeezed, stretched and compressed.; In groups learners sort out more materials into solids, liquids and gases.; Demonstrate the formation of vapour (gaseous state) by boiling water.', 50),
('Basic 2', 'Science', 'science', 'Diversity of Matter', 'Materials', 'B2.1.2.3', 'Understand mixtures, the types, their formation, uses and ways of separating them into their components', 'B2.1.2.3.1', 'Describe a solid', '–solid mixture and explain how to separate the components; Learners watch a video and pictures on solid-solid mixtures; Provide learners with solid materials for them to observe, e.g. sand, gari, saw dust, chalk, charcoal and cowpea.; Learners combine two materials at a time and observe what happens; Learners talk about the mixtures they have formed; Ask learners whether the products they have formed are the same as the individual materials. How will they call the material combinations they have formed?; Assist learners to understand that when they mix two or more things together, they form a mixture and that no new thing forms even though the starting and ending substances may look different from each other.; Explain to learners that they have formed a solid—solid mixture; Learners explore ways of separating the components of the solids-solid mixtures they have prepared; Provide more solid materials for learners to do more group activities; Relate the lesson to everyday life. For example, separation of a mixture of groundnut and sand, sand and stone, and maize and chaff, roasted groundnut and its husks; Learners to separate some common solid-solid mixtures such as sand and stone, iron nails and sand, gari and groundnut.', 60),
('Basic 2', 'Science', 'science', 'Cycles', 'Earth Science', 'B2.2.1.1', 'Recognise that some events in our environment occur recurrently', 'B2.2.1.1.1', 'Recognise the importance of some cyclic natural phenomena such as dry and wet seasons', 'Learners recall events that occur and reoccur in a cyclic manner (day and night, merry-go- round). (Refer to Basic 1).; Lead learners through poems, rhymes, games and discussions to introduce another cyclic event – wet and dry seasons.; Learners discuss what they like and don’t like about the dry season.; Talk about what they like and dislike about the wet season.; Assess learners by asking them to draw and make posters on the dry and wet seasons and colour some human activities that take place during these times.; Lead learners to think critically to identify problems related to wet or dry seasons and how such problems can be solved, e.g. how do people get water during dry season? How do people dry their clothes during wet season? What can be done to solve the problem of school compounds getting muddy during the wet season? NB: Assist learners to understand the concept of seasons.', 70),
('Basic 2', 'Science', 'science', 'Cycles', 'Earth Science', 'B2.2.1.2', 'Recognise the relationship between the Earth and the Sun', 'B2.2.1.2.1', 'Identify sources of light to the earth', 'Learners mention sources of light at home and at the school.; Assemble different sources of light (realia and pictures): stars, torch, lantern, lightning, fireflies, forest fires, light bulbs, candle light etc.; Learners identify and draw sources of light in their environment.; Sort and classify sources of light as artificial or natural.; Learners talk about why and when we need light.; Designs an activity to block light from a torch using a cardboard to illustrate the importance of light.; Discuss with learners: What will happen if there is no light on earth?', 80),
('Basic 2', 'Science', 'science', 'Cycles', 'Earth Science', 'B2.2.1.4', 'Recognise water and air as important natural resources', 'B2.2.1.4.1', 'Find out the qualities of good drinking water', 'Learners mention the sources of water we drink and use in their homes and communities.; Supply learners with samples of water from different sources, i.e. river, pond, well and bottled water. Caution: learners should not taste any of the water samples.; In groups learners examine the water samples for the following: solid particles (using hand lens), colour and odour (smell). Each group presents their findings.; Display to learners, samples of good drinking water and assist them to infer that good drinking water has no colour, and no odour and is free from solid particles; Learners explain what will happen when they drink water that has particles, odour and colour in it', 90),
('Basic 2', 'Science', 'science', 'Cycles', 'Earth Science', 'B2.2.1.4', 'Recognise water and air as important natural resources', 'B2.2.1.4.2', 'Identify uses of air', 'Ask learners to breathe in and out and find out from them what they are breathing in.; In groups learners perform the following activities, e.g. filling balloons, pumping tyres, flying kites, cooling the body, supporting burning and or show pictures of the activities.; Show pictures of people on a boat wearing life jackets, swimmers on inflated balloons on water.; Create real life problems related to the topic for learners to discuss and come out with possible solutions.', 100),
('Basic 2', 'Science', 'science', 'Systems', 'The Human Body Systems', 'B2.3.1.1', 'Recognise that different parts of the human body work interdependently to perform a specific function', 'B2.3.1.1.1', 'Know the functions of the human body parts such as eyes, ears, mouth, nose, arms, legs and hands', 'Learners in a pair share activity observe their friends critically and talk about the parts they see.; Learners engaged to watch an animated video or listen to an animated song or show a picture of the parts of the human body. (Head, neck, eyes, nose, mouth, stomach, legs).; Learners talk about the song or biological uses of the human body in pairs - video and discuss the uses of the parts of the body.; In groups learners brainstorm and talk about what will happen if some parts of the body are absent or not working well?; Learners to present and explain their group ideas orally and/or written.; Write the main biological functions of the human body parts being discussed.; Learners draw and colour any two parts of the body. Note: Counsel any physically challenged child before the lesson.', 110),
('Basic 2', 'Science', 'science', 'Systems', 'Solar System', 'B2.3.2.1', 'Show understanding of the orderliness of the sun, planets and satellites in the solar system as well as the important role of the sun in the solar system', 'B2.3.2.1.1', 'Identify the sun as the main source of light and warmth on earth', 'Learners engaged with these questions: What does the sun look like? Where is the sun located? Do you feel warmer or colder when the sun is out? Why is the sun important to us here on Earth?; In groups learners discuss and present to class what they use the light and the warmth from the sun for.; Learners brainstorm on how life without the sun will be.; Draw a picture of the sun and colour it.', 120),
('Basic 2', 'Science', 'science', 'Forces and Energy', 'Sources and Forms of Energy', 'B2.4.1.1', 'Demonstrate understanding of the concept of energy, its various forms, sources and the ways in which it can be transformed and conserved', 'B2.4.1.1.1', 'Identify everyday applications of energy', 'Learners perform various activities involving the use of energy, e.g. jumping, clapping, pushing objects, walking, switching on the lights etc. in the classroom.; Learners find out what helps them to perform the activities mentioned; Learners watch pictures or videos on people doing activities involving energy. e.g. a person pounding “fufu”, riding a bicycle, fetching water from a well, switching on light, playing music, etc., to reinforce the use of energy; Learners explain what happens to a person who does not eat food for a long time.; Summarise the lesson by explaining that energy is what gives learners and everybody the strength to do everyday activities; Create a poster of a person engaging in an activity that uses energy, e.g. pushing an object, a farmer weeding, fishermen paddling a boat, and display them for discussion. NB: Engage learners in more activities to demonstrate the application of energy', 130),
('Basic 2', 'Science', 'science', 'Forces and Energy', 'Sources and Forms of Energy', 'B2.4.1.2', 'Show understanding of the concept of heat in terms of its importance, effects, sources and transfer from one medium to another', 'B2.4.1.2.1', 'Understand that objects become hot or cold through the loss or gain of heat', 'Learners feel hot and cold substances and discuss their observations.; In a practical activity, learners create heat by rubbing the palms, boiling water, burning candle, etc.; Engage learners in an activity that makes things lose heat, e.g. adding cold water to hot water, leaving a hot substance to stand for some time, unplucking a hot electric iron, or a local box iron, putting a substance in a refrigerator etc.; Provide learners with water and ask learners to plan how to make it hot or cold.', 140),
('Basic 2', 'Science', 'science', 'Forces and Energy', 'Electricity and Electronics', 'B2.4.2.1', 'Demonstrate knowledge of generation of electricity, its transmission and transformation into other forms of energy', 'B2.4.2.1.1', 'Recognise the importance of safety when using electricity', 'Learners mention electrical items they use in the home; Learners view pictures of how people use electricity in the home, school and community and talk about it; Teacher reinforces learners’ ideas on the safe use of electricity; In groups, learners critique pictures of scenarios of someone using electricity in a safe or unsafe way, e.g. plugging uninsulated (naked) wires into sockets, climbing electricity pole, touching water being heated with a water heater; Teacher reinforces learners’ ideas by mentioning the safety ways of using electricity.; learners to know basic safety tips on electricity such as wearing of insulator (plastic/or any other material) shoes and slippers, making sure hands are dry etc., plugging sockets with the aid of insulating materials (plastic/wood etc.) rather than metals; Enquire from learners why electrical gadgets are covered with plastics and wooden materials', 150),
('Basic 2', 'Science', 'science', 'Forces and Energy', 'Electricity and Electronics', 'B2.4.2.2', 'Know the functions and assemblage of basic electronics components', 'B2.4.2.2.2', 'Investigate the function of batteries in electronic devices', 'Learners mention common examples of household electronic appliances.; Provide learners with electronic toys that operate on batteries.; Learners discuss how the toys will behave without the battery; Engage learners in an activity to match some named electronic appliances with their uses.; In groups, learners discuss other gadgets in the home that use batteries.; Assist learners to draw and colour any one electronic gadget of their choice.; Learners build a paper circuit using a graphite pencil, battery and LED.', 160),
('Basic 2', 'Science', 'science', 'Forces and Energy', 'Forces and Movement', 'B2.4.3.1', 'Know that movement is caused by applied forces due to the release of stored energy', 'B2.4.3.1.1', 'Discover the effects of forces on objects', 'Provide different scenarios to let learners know that forces cause objects to move or stop, e.g. kicking a ball, pushing a chair or pulling a rope etc.; Learners engaged to do the following activities: scrambling of paper and metal foils, pushing objects in the classroom, squeezing empty plastic bottles etc.; Learners talk about the activities they performed.; Emphasize the effects of forces on objects, e.g. changing shape, making it move, changing the direction of movement and reducing the speed of a moving object.', 170),
('Basic 2', 'Science', 'science', 'Forces and Energy', 'Forces and Movement', 'B2.4.3.2', 'Recognise some simple machines and their advantages of making work easier', 'B2.4.3.2.1', 'Identify simple machines used for specific work', 'Display simple machines, e.g. pair of scissors, bottle openers, forceps, claw hammer, screw driver, etc.; Learners in groups identify the simple machines displayed; Demonstrate how to use simple machines to learners; Provide learners with the following: a piece of cloth, a nail stuck in wood, a bottle of soft drink, a screw in a piece of wood; Learners identify and use specific simple machine for removing bottle tops, cutting a piece of cloth, removing a nail stuck in wood and removing screw from a piece of wood; Individually or in groups, learners draw their favorite simple machines and colour them.; Show video and pictures of simple machines in their everyday life.; Learners create simple machines from cardboards; Ask learners the machines they will use to do the following activities: weeding, sweeping, digging, tightening a bolt and knot, and explain why', 180),
('Basic 2', 'Science', 'science', 'Humans and the Environment', 'Personal Hygiene and Sanitation', 'B2.5.1.1', 'Recognise the importance of personal hygiene', 'B2.5.1.1.1', 'Explain how to keep the body clean and describe why it is important', 'Learners sing songs, tell stories, and recite poems and rhymes on personal hygiene.; Let learners mention some activities they undertake with their fingers and explain to them why it is important to keep the finger nails clean.; Learners demonstrate how to use items for trimming of hair and nails correctly.; Learners explain why they will not share their personal effects with friends.; Find out from learners what will happen if they leave their finger nails and hair to grow without cutting or trimming them regularly.', 190),
('Basic 2', 'Science', 'science', 'Humans and the Environment', 'Personal Hygiene and Sanitation', 'B2.5.1.1', 'Recognise the importance of personal hygiene', 'B2.5.1.1.2', 'Know the need for keeping classrooms and school compound clean', 'They observe the ceiling, windows, floors and their sitting areas within the classroom and communicate their findings.; Learners tour the school compound and tell whether it is a clean or dirty compound.; Learners discuss the need to keep the classroom and school surroundings clean to avoid sickness, to destroy the hiding places of mosquitoes, snakes, wall geckos and to ensure good ventilation.', 200),
('Basic 2', 'Science', 'science', 'Humans and the Environment', 'Diseases', 'B2.5.2.1', 'Know common diseases of humans, causes, symptoms, effects and prevention', 'B2.5.2.1.1', 'Identify causes and prevention of ringworm', 'Show pictures of people suffering from ringworm.; Guide learners to bring out possible causes of ringworm and other skin diseases such as eczema.; Discuss the modes of prevention of skin diseases such as good personal hygiene and not sharing personal items with infected persons.; Ask learners to compose a rhyme or song on the prevention of ringworm.', 210),
('Basic 2', 'Science', 'science', 'Humans and the Environment', 'Diseases', 'B2.5.2.1', 'Know common diseases of humans, causes, symptoms, effects and prevention', 'B2.5.2.1.2', 'Name some common water-borne diseases and their prevention', 'In groups learners observe containers of dirty water and clean water.; Show pictures or videos of people suffering from diarrhoea, cholera, and typhoid.; Ask learners to identify which sample of water (dirty or clean), is likely to contain microorganisms that cause diseases.; Let learners discuss how they will prevent themselves from contracting water-borne diseases (boiling water, filtering water, etc.).; Let learners create posters, compose songs or rhymes on how to prevent water- borne diseases.', 220),
('Basic 2', 'Science', 'science', 'Humans and the Environment', 'Science and Industry', 'B2.5.3.1', 'Recognise the impact of science and technology in society', 'B2.5.3.1.1', 'Identify the technological devices used in the community and describe their impact', 'Prior to the lesson, give learners an assignment to investigate how people communicated, travelled, sought medical care, etc. in the olden days (in the absence of modern-day technological inventions); Engage learners to communicate their findings based on the investigations; Learners name some technological devices they see in the school, at home, in the market places, hospitals, mosque, churches, bus stations, airport, etc.; Present some products of technology that can be seen in the community to learners, e.g. mobile phones, computers, school bag, sewing machines and fan; Facilitate a session where learners operate some common devices such as mobile phones, laptops, toy cars etc.; Let learners brainstorm to find out what will happen if there were no modern technological devices in the community; Ask learners to draw a technological device that will improve their communities in future.', 230),
('Basic 2', 'Science', 'science', 'Humans and the Environment', 'Science and Industry', 'B2.5.3.2', 'Exhibit knowledge of food processing and preservation', 'B2.5.3.2.1', 'Know the ways foods are processed for consumption', 'Let learners draw and display the foods they eat every day.; Ask learners to state why food must be processed before it is consumed.; In groups learners discuss ways of processing foods for consumption. e.g., roasting, frying, and boiling, and communicate their ideas to the whole class.; Present samples of raw food stuffs to learners and let them talk about how they can process them for consumption.; Emphasize on key processing methods such as washing, boiling, frying, baking, roasting etc. NB: Assign learners to find out how foods are processed for consumption in their communities before the lesson.', 240),
('Basic 2', 'Science', 'science', 'Humans and the Environment', 'Climate Change', 'B2.5.4.1', 'Know that climate change is one of the most important environmental issues facing the world today', 'B2.5.4.1.1', 'Explain some common human activities that are harmful to the environment', 'Let learners come out with different activities that could harm the environment (bush burning, burning of rubbish, throwing rubbish into water bodies).; Let learners determine if they could be harmed by these activities. (What will happen to you if you breathe in smoke? what will happen if you drink water from a contaminated source?); Explain to learners that fossil fuels like the petrol used in cars is causing the world to become warmer, affecting the weather.; If it is a farming community, how has the weather patterns changed recently?; If it''s a fishing community by the ocean, has the ocean been taking away the land?', 250);
